namespace K {
    ll n, m, k, c, d;
}
vector<ll> vr[55];
ll lr[50];
int main()
{
    ll N = 50*99+1, M, K = INF;
    vector<vector<Edge>> g(N);
    ll s, t;

    cin >> K::n >> K::m >> K::k >> K::c >> K::d;

    ll tim = 99;
    for (int i = 1; i <= K::k; ++i) {
        cin >> lr[i];
        addEdge(g, 0, lr[i], 1, 0);
