        for (int i = 2; i <= K::n; ++i)
            addEdge(g, j*50+i, (j+1)*50+i, 50, K::c);
    }
    for (int j = 1; j < tim; ++j) {
        addEdge(g, j*50+1, 1, 50, 0);
    }
    for (int i = 0; i < K::m; ++i) {
        ll x, y;
        cin >> x >> y;
        vr[x].push_back(y);
