struct SPFAMinCost {
    struct Edge {
        int to, rev, cap, cost;
    };

    int N, S, T;
    vector<vector<Edge>> g;

    SPFAMinCost(int n, int s, int t) : N(n), S(s), T(t), g(n) {}

    int add_edge(int v, int u, int cap, int cost) {
        Edge a{u, (int)g[u].size(), cap, cost};
        Edge b{v, (int)g[v].size(), 0, -cost};
        g[v].push_back(a);
        g[u].push_back(b);
        return (int)g[v].size() - 1;
    }

    pair<int,int> run() {
        int flow = 0, total_cost = 0;
        const int INF = INT_MAX / 2;

        while (true) {
            vector<int> dist(N, INF), prev_v(N, -1), prev_e(N, -1), max_f(N, 0);
            vector<char> inq(N, 0);
            deque<int> q;

            dist[S] = 0;
            max_f[S] = INT_MAX;
            q.push_back(S);
            inq[S] = 1;

            while (!q.empty()) {
                int v = q.front();
                q.pop_front();
                inq[v] = 0;

                for (int i = 0; i < (int)g[v].size(); ++i) {
                    Edge &e = g[v][i];
                    if (e.cap <= 0) continue;

                    if (dist[e.to] > dist[v] + e.cost) {
                        dist[e.to] = dist[v] + e.cost;
                        prev_v[e.to] = v;
                        prev_e[e.to] = i;
                        max_f[e.to] = min(max_f[v], e.cap);

                        if (!inq[e.to]) {
                            q.push_back(e.to);
                            inq[e.to] = 1;
                        }
                    }
                }
            }

            if (dist[T] == INF) break;

            int add = max_f[T];
            for (int v = T; v != S; v = prev_v[v]) {
                Edge &e = g[prev_v[v]][prev_e[v]];
                total_cost += add * e.cost;
                e.cap -= add;
                g[v][e.rev].cap += add;
            }

            flow += add;
        }

        return make_pair(flow, total_cost);
    }
};

int main() {
