#include<bits/stdc++.h>
using namespace std;
constexpr int INF = 0x3f3f3f3f;
constexpr int MAXN = 10000;
constexpr int MAXE = 3000000;

int first_edge[MAXN], dest[MAXE], capacity[MAXE], price[MAXE], nxt_edge[MAXE];
int dist[MAXN], used[MAXN], parent[MAXN], parent_edge[MAXN];
int source, target, edge_total;
int queue_data[MAXN * 10], q_head, q_tail;

void add_arc(int u, int v, int cp, int cs) {
    dest[edge_total] = v; capacity[edge_total] = cp; price[edge_total] = cs;
    nxt_edge[edge_total] = first_edge[u]; first_edge[u] = edge_total++;
    dest[edge_total] = u; capacity[edge_total] = 0; price[edge_total] = -cs;
    nxt_edge[edge_total] = first_edge[v]; first_edge[v] = edge_total++;
}

bool spfa_shortest_path() {
    q_head = 0; q_tail = 0;
    memset(dist, INF, sizeof(dist));
    memset(used, 0, sizeof(used));
    memset(parent, -1, sizeof(parent));
    dist[source] = 0;
    used[source] = 1;
    queue_data[q_tail++] = source;
    while (q_head < q_tail) {
        int u = queue_data[q_head++];
        used[u] = 0;
        for (int e = first_edge[u]; e != -1; e = nxt_edge[e]) {
            int v = dest[e];
            if (capacity[e] > 0 && dist[v] > dist[u] + price[e]) {
                dist[v] = dist[u] + price[e];
                parent[v] = u;
                parent_edge[v] = e;
                if (!used[v]) {
                    used[v] = 1;
                    queue_data[q_tail++] = v;
                }
            }
        }
    }
    return dist[target] < INF;
}

int total_min_cost() {
    int answer = 0;
    while (spfa_shortest_path()) {
        int push = INF;
        for (int v = target; v != source; v = parent[v]) {
            push = min(push, capacity[parent_edge[v]]);
        }
        for (int v = target; v != source; v = parent[v]) {
            int e = parent_edge[v];
            capacity[e] -= push;
            capacity[e ^ 1] += push;
        }
        answer += dist[target] * push;
    }
    return answer;
}

