int head[MAXN], to[MAXE], cap[MAXE], cost[MAXE], nxt[MAXE];
int dis[MAXN], inq[MAXN], pre[MAXN], pree[MAXN];
int SRC, SNK, edges_cnt;

void add_edge(int u, int v, int c, int w) {
    to[edges_cnt] = v; cap[edges_cnt] = c; cost[edges_cnt] = w; nxt[edges_cnt] = head[u]; head[u] = edges_cnt++;
    to[edges_cnt] = u; cap[edges_cnt] = 0; cost[edges_cnt] = -w; nxt[edges_cnt] = head[v]; head[v] = edges_cnt++;
}

int min_cost_flow() {
    int total_cost = 0;
    while (true) {
        queue<int> q;
        memset(dis, INF, sizeof(dis));
        memset(inq, 0, sizeof(inq));
        memset(pre, -1, sizeof(pre));
        memset(pree, -1, sizeof(pree));
        dis[SRC] = 0;
        q.push(SRC);
        inq[SRC] = 1;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            inq[u] = 0;
            for (int e = head[u]; e != -1; e = nxt[e]) {
                int v = to[e];
                if (cap[e] > 0 && dis[v] > dis[u] + cost[e]) {
                    dis[v] = dis[u] + cost[e];
                    pre[v] = u;
                    pree[v] = e;
                    if (!inq[v]) {
                        inq[v] = 1;
                        q.push(v);
                    }
                }
            }
        }
        if (dis[SNK] >= INF) break;
        int add = INF;
        for (int v = SNK; v != SRC; v = pre[v]) add = min(add, cap[pree[v]]);
        for (int v = SNK; v != SRC; v = pre[v]) {
            cap[pree[v]] -= add;
            cap[pree[v] ^ 1] += add;
        }
        total_cost += dis[SNK] * add;
    }
    return total_cost;
}

