using ll = long long;
const ll INF = (ll)1e18;

struct Edge {
    int to, rev;
    ll cap, cost;
};

class MinCostFlow {
    int n, s, t;
    vector<vector<Edge>> g;
    vector<ll> dist;
    vector<int> prevv, preve, inq;
public:
    MinCostFlow(int n_, int s_, int t_) : n(n_), s(s_), t(t_), g(n_+1), dist(n_+1), prevv(n_+1), preve(n_+1), inq(n_+1, 0) {}
    void add_edge(int from, int to, ll cap, ll cost) {
        Edge f{to, (int)g[to].size(), cap, cost};
        Edge r{from, (int)g[from].size(), 0, -cost};
        g[from].push_back(f);
        g[to].push_back(r);
    }
    ll min_cost_flow(ll f) {
        ll res = 0;
        while (f > 0) {
            fill(dist.begin(), dist.end(), INF);
            dist[s] = 0;
            queue<int> q;
            q.push(s);
            inq[s] = 1;
            while (!q.empty()) {
                int now = q.front(); q.pop();
                inq[now] = 0;
                for (int i = 0; i < (int)g[now].size(); ++i) {
                    Edge &e = g[now][i];
                    if (e.cap > 0 && dist[now] + e.cost < dist[e.to]) {
                        dist[e.to] = dist[now] + e.cost;
                        prevv[e.to] = now;
                        preve[e.to] = i;
                        if (!inq[e.to]) {
                            inq[e.to] = 1;
                            q.push(e.to);
                        }
                    }
                }
            }
            if (dist[t] == INF) return -1;
            ll d = f;
            for (int v = t; v != s; v = prevv[v])
                d = min(d, g[prevv[v]][preve[v]].cap);
            f -= d;
            res += d * dist[t];
            for (int v = t; v != s; v = prevv[v]) {
                Edge &e = g[prevv[v]][preve[v]];
                e.cap -= d;
                g[v][e.rev].cap += d;
            }
        }
        return res;
    }
};

