    int to, rev;
    ll cap, cost;
};

vector<Edge> g[MAXN];
ll dis[MAXN];
int pv[MAXN], pe[MAXN];
bool ins[MAXN];
int ncnt, src, snk;

void init_graph(int n, int s, int t) {
    for (int i = 0; i <= n; ++i) g[i].clear();
    ncnt = n;
    src = s;
    snk = t;
}

void add_arc(int u, int v, ll cap, ll cost) {
    g[u].push_back({v, (int)g[v].size(), cap, cost});
    g[v].push_back({u, (int)g[u].size() - 1, 0, -cost});
}

ll min_cost_max_flow(ll need) {
    ll ans = 0;
    while (need > 0) {
        fill(dis, dis + ncnt, INF);
        dis[src] = 0;
        deque<int> q;
        q.push_back(src);
        ins[src] = true;
        while (!q.empty()) {
            int u = q.front();
            q.pop_front();
            ins[u] = false;
            for (int i = 0; i < (int)g[u].size(); ++i) {
                Edge &e = g[u][i];
                if (e.cap > 0 && dis[u] + e.cost < dis[e.to]) {
                    dis[e.to] = dis[u] + e.cost;
                    pv[e.to] = u;
                    pe[e.to] = i;
                    if (!ins[e.to]) {
                        ins[e.to] = true;
                        q.push_back(e.to);
                    }
                }
            }
        }
        if (dis[snk] == INF) return -1;
        ll add = need;
        for (int v = snk; v != src; v = pv[v])
            add = min(add, g[pv[v]][pe[v]].cap);
        need -= add;
        ans += add * dis[snk];
        for (int v = snk; v != src; v = pv[v]) {
            Edge &e = g[pv[v]][pe[v]];
            e.cap -= add;
            g[v][e.rev].cap += add;
        }
    }
    return ans;
}

