#include <bits/stdc++.h>
using namespace std;

using ll = long long;

class MinCostMaxFlow {
private:
    static constexpr int MX = 5500;
    static constexpr ll INF = 1000000007LL;

    struct Edge {
        int to, cost, rev, cap;
    };

    int n, m, k, c, d;
    int u, v, mx;
    int s, t, mf;
    int tr[MX];
    ll ans, dis[MX];
    vector<Edge> adj[MX];
    priority_queue<pair<ll, int>, vector<pair<ll, int>>, greater<pair<ll, int>>> pq;

    int at(int node, int time) const {
        return node + time * n;
    }

    void addEdge(int u, int v, int cost, int cap) {
        int szu = adj[u].size();
        int szv = adj[v].size();
        adj[u].push_back({v, cost, szv, cap});
        adj[v].push_back({u, -cost, szu, 0});
    }

    void dijkstra() {
        fill(dis, dis + MX, INF);
        pq.push({dis[s] = 0, s});
        while (!pq.empty()) {
            auto [du, x] = pq.top();
            pq.pop();
            if (du > dis[x]) continue;
            for (const Edge &e : adj[x]) {
                if (e.cap > 0 && dis[e.to] > du + e.cost) {
                    tr[e.to] = e.rev;
                    pq.push({dis[e.to] = du + e.cost, e.to});
                }
            }
        }
    }

    void trace() {
        int aug = k, cur = t;
        while (cur != s) {
            const Edge &rev = adj[cur][tr[cur]];
            int pre = rev.to;
            int fwd = rev.rev;
            aug = min(aug, adj[pre][fwd].cap);
            cur = pre;
        }
        mf += aug;
        ans += aug * dis[t];
        cur = t;
        while (cur != s) {
            Edge &rev = adj[cur][tr[cur]];
            int pre = rev.to;
            int fwd = rev.rev;
            rev.cap += aug;
            adj[pre][fwd].cap -= aug;
            cur = pre;
        }
    }

public:
    void run() {
        ios::sync_with_stdio(false);
        cin.tie(nullptr);
        cin >> n >> m >> k >> c >> d;
        s = MX - 2;
        t = MX - 1;
        mf = 0;
        ans = 0;
        mx = n + k;
        for (int i = 0; i < k; i++) {
            cin >> u;
            addEdge(s, at(u, 0), 0, 1);
        }
        for (int i = 0; i <= mx; i++) {
            addEdge(at(1, i), t, c * i, k);
        }
        for (int i = 1; i <= n; i++) {
            for (int j = 0; j < mx; j++) {
                addEdge(at(i, j), at(i, j + 1), 0, k);
            }
        }
        while (m--) {
            cin >> u >> v;
            for (int i = 1; i <= k; i++) {
                for (int j = 0; j < mx; j++) {
                    addEdge(at(u, j), at(v, j + 1), d * (2 * i - 1), 1);
                    addEdge(at(v, j), at(u, j + 1), d * (2 * i - 1), 1);
                }
            }
        }
        while (mf < k) {
            dijkstra();
            trace();
        }
        cout << ans;
    }
};

int main() {
    MinCostMaxFlow solver;
    solver.run();
    return 0;
}

