#include <bits/stdc++.h>
using namespace std;

const int INF = INT_MAX;
const int MAXN = 10001;

struct Edge {
    int to, rev, cap, cost;
};

vector<Edge> g[MAXN];
int nodeCnt;
int dist[MAXN], prevV[MAXN], prevE[MAXN];
bool inQueue[MAXN];

int addNodes(int cnt) {
    while (cnt--) g[nodeCnt++].clear();
    return nodeCnt - 1;
}

void addEdge(int u, int v, int cap, int cost) {
    g[u].push_back({v, (int)g[v].size(), cap, cost});
    g[v].push_back({u, (int)g[u].size() - 1, 0, -cost});
}

bool spfa(int s, int t) {
    fill(dist, dist + nodeCnt, INF);
    fill(inQueue, inQueue + nodeCnt, false);

    queue<int> q;
    dist[s] = 0;
    q.push(s);
    inQueue[s] = true;

    while (!q.empty()) {
        int u = q.front();
        q.pop();
        inQueue[u] = false;

        for (int i = 0; i < (int)g[u].size(); ++i) {
            Edge &e = g[u][i];
            int v = e.to;

            if (e.cap > 0 && dist[v] > dist[u] + e.cost) {
                dist[v] = dist[u] + e.cost;
                prevV[v] = u;
                prevE[v] = i;

                if (!inQueue[v]) {
                    inQueue[v] = true;
                    q.push(v);
                }
            }
        }
    }

    return dist[t] != INF;
}

int main() {
    int n, m, k, c, d;
    scanf("%d %d %d %d %d", &n, &m, &k, &c, &d);

    nodeCnt = 0;
    int L = max(n, k) * 2;

    addNodes(L * n);
    int s = addNodes(1);
    int t = addNodes(1);

    for (int j = 0; j < k; ++j) {
        int a;
        scanf("%d", &a);
        --a;
        addEdge(s, a, 1, 0);
    }

    for (int z = 0; z < m; ++z) {
        int u, v;
        scanf("%d %d", &u, &v);
        --u;
        --v;

        for (int i = 0; i + 1 < L; ++i) {
            int u1 = u + i * n;
            int v1 = v + (i + 1) * n;
            int u2 = u + (i + 1) * n;
            int v2 = v + i * n;

            for (int j = 0; j < k; ++j) {
                int w = c + d * (2 * j + 1);
                addEdge(u1, v1, 1, w);
                addEdge(v2, u2, 1, w);
            }
        }
    }

    for (int i = 0; i + 1 < L; ++i) {
        for (int j = 0; j < n; ++j) {
            int u = j + i * n;
            int v = j + (i + 1) * n;
            addEdge(u, v, INF, c);
        }
    }

    for (int i = 0; i < L; ++i)
        addEdge(i * n, t, INF, 0);

    int flow = 0, cost = 0;

    while (flow < k) {
        if (!spfa(s, t)) break;

        int add = INF;
        for (int v = t; v != s; v = prevV[v])
            add = min(add, g[prevV[v]][prevE[v]].cap);

        for (int v = t; v != s; v = prevV[v]) {
            Edge &e = g[prevV[v]][prevE[v]];
            e.cap -= add;
            g[v][e.rev].cap += add;
        }

        flow += add;
        cost += add * dist[t];
    }

    printf("%d\n", cost);
    return 0;
}

