#include <bits/stdc++.h>
using namespace std;

using ll = long long;
const ll INF = 1000000000LL;

struct MinCostFlow {
    struct Edge {
        int to, rev;
        ll cap, flow, cost;
    };

    int n;
    vector<vector<Edge>> g;
    vector<ll> dist;
    vector<int> prevv, preve, inq;

    MinCostFlow(int n) : n(n), g(n) {}

    void add_edge(int v, int u, ll cap, ll cost) {
        g[v].push_back({u, (int)g[u].size(), cap, 0, cost});
        g[u].push_back({v, (int)g[v].size() - 1, 0, 0, -cost});
    }

    pair<ll, ll> min_cost_flow(int s, int t) {
        ll flow = 0, total_cost = 0;

        while (true) {
            dist.assign(n, INF);
            prevv.assign(n, -1);
            preve.assign(n, -1);
            inq.assign(n, 0);

            queue<int> q;
            dist[s] = 0;
            q.push(s);
            inq[s] = 1;

            while (!q.empty()) {
                int v = q.front();
                q.pop();
                inq[v] = 0;

                for (int i = 0; i < (int)g[v].size(); ++i) {
                    Edge &e = g[v][i];
                    if (e.cap <= e.flow) continue;

                    if (dist[e.to] > dist[v] + e.cost) {
                        dist[e.to] = dist[v] + e.cost;
                        prevv[e.to] = v;
                        preve[e.to] = i;

                        if (!inq[e.to]) {
                            q.push(e.to);
                            inq[e.to] = 1;
                        }
                    }
                }
            }

            if (dist[t] == INF) break;

            ll add = INF;
            for (int v = t; v != s; v = prevv[v]) {
                Edge &e = g[prevv[v]][preve[v]];
                add = min(add, e.cap - e.flow);
            }

            flow += add;

            for (int v = t; v != s; v = prevv[v]) {
                Edge &e = g[prevv[v]][preve[v]];
                e.flow += add;
                g[v][e.rev].flow -= add;
                total_cost += add * e.cost;
            }
        }

        return {flow, total_cost};
    }
};

