class MinCostFlow {
    int n;
    vector<Edge> edges;
    vector<vector<int>> adj;
    vector<int> dist, pot, prevv, preve;

public:
    MinCostFlow(int n_) : n(n_), adj(n_), dist(n_), pot(n_, 0), prevv(n_), preve(n_) {}

    void add_edge(int v, int u, int cap, int cost) {
        int id = (int)edges.size();
        edges.push_back({u, cap, 0, cost});
        edges.push_back({v, 0, 0, -cost});
        adj[v].push_back(id);
        adj[u].push_back(id ^ 1);
    }

    pair<int, int> min_cost_flow(int s, int t) {
        int flow = 0, flow_cost = 0;

        while (true) {
            fill(dist.begin(), dist.end(), INF);
            dist[s] = 0;

            priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> pq;
            pq.push({0, s});

            while (!pq.empty()) {
                auto [d, v] = pq.top();
                pq.pop();
                if (d != dist[v]) continue;

                for (int id : adj[v]) {
                    Edge &e = edges[id];
                    if (e.cap - e.flow <= 0) continue;

                    int nd = d + e.cost + pot[v] - pot[e.to];
                    if (nd < dist[e.to]) {
                        dist[e.to] = nd;
                        prevv[e.to] = v;
                        preve[e.to] = id;
                        pq.push({nd, e.to});
                    }
                }
            }

            if (dist[t] == INF) break;

            for (int i = 0; i < n; ++i) pot[i] += dist[i];

            int add = INF - flow;
            for (int v = t; v != s; v = prevv[v]) {
                Edge &e = edges[preve[v]];
                add = min(add, e.cap - e.flow);
            }

            flow += add;
            for (int v = t; v != s; v = prevv[v]) {
                Edge &e = edges[preve[v]];
                e.flow += add;
                edges[preve[v] ^ 1].flow -= add;
                flow_cost += add * e.cost;
            }
        }

        return {flow, flow_cost};
    }
};

