        for (int j = 0; j < T - 1; ++j) {
            mcf.add_edge(i * T + j, i * T + j + 1, INF, c);
        }
    }

    for (int i = 0; i < T; ++i) {
        mcf.add_edge(i, N + 1, INF, 0);
    }

    for (int i = 0; i < k; ++i) {
        int x;
