struct MinCostMaxFlow {
    int head[MAXP], ecnt;
    bool used[MAXP];
    int dist[MAXP];
    Edge edges[MAXE];
    int src, sink, nodeCnt;

    MinCostMaxFlow() : ecnt(1), src(1), sink(2), nodeCnt(2) {
        memset(head, 0, sizeof(head));
    }

    inline void addRaw(int a, int b, int cost, int cap) {
        ++ecnt;
        edges[ecnt].to = b;
        edges[ecnt].cap = cap;
        edges[ecnt].cost = cost;
        edges[ecnt].nxt = head[a];
        head[a] = ecnt;
    }

    inline void addEdge(int a, int b, int cost, int cap) {
        addRaw(a, b, cost, cap);
        addRaw(b, a, -cost, 0);
    }

    bool spfa() {
        for (int i = 1; i <= nodeCnt; ++i) {
            used[i] = false;
            dist[i] = INF;
        }
        int q[MAXP], qh = 0, qt = 0;
