            used[x] = false;
            for (int e = head[x]; e; e = edges[e].nxt) {
                if (!edges[e].cap) continue;
                int y = edges[e].to;
                if (dist[y] > dist[x] + edges[e].cost) {
                    dist[y] = dist[x] + edges[e].cost;
                    if (!used[y]) {
