#include <bits/stdc++.h>
using namespace std;

using ll = long long;

struct Edge {
    int from, to, cap, flow, cost;
};

const int N = 14043;
const ll INF = (ll)4e18;

vector<Edge> edges;
vector<int> adj[N];

ll potential[N], dist[N];
int pv[N], pe[N];

int S = N - 2;
int T = N - 1;
ll answer = 0;

void addEdge(int u, int v, int cap, int cost) {
    adj[u].push_back((int)edges.size());
    edges.push_back({u, v, cap, 0, cost});
    adj[v].push_back((int)edges.size());
    edges.push_back({v, u, 0, 0, -cost});
}

void dijkstra() {
    fill(dist, dist + N, INF);
    fill(pv, pv + N, -1);
    fill(pe, pe + N, -1);

    priority_queue<pair<ll, int>, vector<pair<ll, int>>, greater<pair<ll, int>>> pq;
    dist[S] = 0;
    pq.push({0, S});

    while (!pq.empty()) {
        auto cur = pq.top();
        pq.pop();

        ll d = cur.first;
        int u = cur.second;

        if (d != dist[u]) continue;

        for (int id : adj[u]) {
            if (edges[id].cap - edges[id].flow <= 0) continue;

            int v = edges[id].to;
            ll w = (ll)edges[id].cost + potential[u] - potential[v];

            if (dist[v] > d + w) {
                dist[v] = d + w;
                pv[v] = u;
                pe[v] = id;
                pq.push({dist[v], v});
            }
        }
    }

    for (int i = 0; i < N; i++)
        if (dist[i] < INF / 2)
            potential[i] += dist[i];
}

void augment() {
    int cur = T;
    while (cur != S) {
        int id = pe[cur];
        edges[id].flow++;
        edges[id ^ 1].flow--;
        cur = pv[cur];
    }
    answer += potential[T];
}

