#include <bits/stdc++.h>
using namespace std;

using ll = long long;

struct Edge {
    int y, c, f, cost;
};

const int N = 14043;
const ll INF = (ll)1e18;

vector<Edge> e;
vector<int> adj[N];

ll d[N];
int p[N], pe[N];
bool used[N];

int S = N - 2;
int T = N - 1;
ll ans = 0;

int rem(int id) {
    return e[id].c - e[id].f;
}

void add_edge(int u, int v, int cap, int cost) {
    adj[u].push_back((int)e.size());
    e.push_back({v, cap, 0, cost});
    adj[v].push_back((int)e.size());
    e.push_back({u, 0, 0, -cost});
}

void augment() {
    fill(d, d + N, INF);
    fill(p, p + N, -1);
    fill(pe, pe + N, -1);
    fill(used, used + N, false);

    deque<int> q;
    d[S] = 0;
    q.push_back(S);
    used[S] = true;

    while (!q.empty()) {
        int u = q.front();
        q.pop_front();
        used[u] = false;

        for (int id : adj[u]) {
            if (rem(id) <= 0) continue;

            int v = e[id].y;
            ll nd = d[u] + e[id].cost;

            if (nd < d[v]) {
                d[v] = nd;
                p[v] = u;
                pe[v] = id;

                if (!used[v]) {
                    used[v] = true;
                    if (!q.empty() && d[v] < d[q.front()])
                        q.push_front(v);
                    else
                        q.push_back(v);
                }
            }
        }
    }

    int cur = T;
    while (cur != S) {
        int id = pe[cur];
        e[id].f++;
        e[id ^ 1].f--;
        cur = p[cur];
    }

    ans += d[T];
}

int main() {
    ios::sync_with_stdio(false);
