};

class MinCostFlow {
public:
    int n;
    vector<vector<Edge>> graph;

    MinCostFlow(int n_) : n(n_), graph(n_) {}

    void addEdge(int from, int to, int cap, int cost) {
        Edge f{to, (int)graph[to].size(), cap, cost};
        Edge r{from, (int)graph[from].size(), 0, -cost};
        graph[from].push_back(f);
        graph[to].push_back(r);
    }

    pair<int,int> minCostMaxFlow(int s, int t, int maxf) {
        const int INF = INT_MAX / 2;
        vector<int> pot(n, 0);
        int flow = 0, cost = 0;
        vector<int> dist(n), prevv(n), preve(n);

        while (flow < maxf) {
            fill(dist.begin(), dist.end(), INF);
            dist[s] = 0;
            priority_queue<pair<int,int>, vector<pair<int,int>>, greater<pair<int,int>>> pq;
            pq.push({0, s});

            while (!pq.empty()) {
                auto cur = pq.top(); pq.pop();
                int d = cur.first;
                int v = cur.second;
                if (d != dist[v]) continue;

                for (int i = 0; i < (int)graph[v].size(); ++i) {
                    Edge &e = graph[v][i];
                    if (e.cap <= 0) continue;
                    int nd = d + e.cost + pot[v] - pot[e.to];
                    if (nd < dist[e.to]) {
                        dist[e.to] = nd;
                        prevv[e.to] = v;
                        preve[e.to] = i;
                        pq.push({nd, e.to});
                    }
                }
            }

            if (dist[t] == INF) break;

            int pathCost = dist[t] + pot[t] - pot[s];

            for (int v = 0; v < n; ++v)
                if (dist[v] < INF) pot[v] += dist[v];

            int add = maxf - flow;
            for (int v = t; v != s; v = prevv[v])
                add = min(add, graph[prevv[v]][preve[v]].cap);

            flow += add;
            cost += add * pathCost;

            for (int v = t; v != s; v = prevv[v]) {
                Edge &e = graph[prevv[v]][preve[v]];
                e.cap -= add;
                graph[v][e.rev].cap += add;
            }
        }

        return {flow, cost};
    }
};

