struct EdgeList {
    int n;
    vector<int> head, to, cap, cost, nxt;

    EdgeList(int n_) : n(n_), head(n_, -1) {}

    void addEdge(int u, int v, int c, int w) {
        to.push_back(v);
        cap.push_back(c);
        cost.push_back(w);
        nxt.push_back(head[u]);
        head[u] = (int)to.size() - 1;

        to.push_back(u);
        cap.push_back(0);
        cost.push_back(-w);
        nxt.push_back(head[v]);
        head[v] = (int)to.size() - 1;
    }

    pair<int,int> minCostFlow(int s, int t, int need) {
        const int INF = INT_MAX / 2;
        vector<int> pot(n, 0);
        int flow = 0, totalCost = 0;

        while (flow < need) {
            vector<int> dist(n, INF), prevv(n, -1), preve(n, -1);
            dist[s] = 0;
            set<pair<int,int>> pq;
            pq.insert({0, s});

            while (!pq.empty()) {
                auto it = pq.begin();
                int d = it->first;
                int v = it->second;
                pq.erase(it);
                if (d != dist[v]) continue;

                for (int e = head[v]; e != -1; e = nxt[e]) {
                    if (cap[e] <= 0) continue;
                    int nd = d + cost[e] + pot[v] - pot[to[e]];
                    if (nd < dist[to[e]]) {
                        if (dist[to[e]] != INF)
                            pq.erase({dist[to[e]], to[e]});
                        dist[to[e]] = nd;
                        prevv[to[e]] = v;
                        preve[to[e]] = e;
                        pq.insert({nd, to[e]});
                    }
                }
            }

            if (dist[t] == INF) break;

            int pathCost = dist[t] + pot[t] - pot[s];

            for (int v = 0; v < n; ++v)
                if (dist[v] < INF) pot[v] += dist[v];

            int add = need - flow;
            for (int v = t; v != s; v = prevv[v])
                add = min(add, cap[preve[v]]);

            flow += add;
            totalCost += add * pathCost;

            for (int v = t; v != s; v = prevv[v]) {
                int e = preve[v];
                cap[e] -= add;
                cap[e ^ 1] += add;
            }
        }

        return {flow, totalCost};
    }
};

