    int i = G[u].size();
    int j = G[v].size();
    G[u].push_back({v, c, w, j});
    G[v].push_back({u, 0, -w, i});
  }

  ll run(int s, int t, ll f) {
    const int N = G.size();
    ll res = 0;
    std::vector<ll> H(N);
    std::vector<ll> D(N);
    const ll INF = 1e18;
    std::vector<int> PE(N), PV(N);
    while (f > 0) {
      std::priority_queue<std::pair<ll, int>> q;
      std::fill(D.begin(), D.end(), INF);
      D[s] = 0;
      q.emplace(0, s);
      while (!q.empty()) {
        ll d = -q.top().first;
        int u = q.top().second;
        q.pop();
        if (D[u] < d) continue;
        for (int i = 0; i < (int)G[u].size(); i++) {
          edge e = G[u][i];
          if (e.c > 0 && D[e.v] > D[u] + e.w + H[u] - H[e.v]) {
            D[e.v] = D[u] + e.w + H[u] - H[e.v];
            q.emplace(-D[e.v], e.v);
