int to[M], cap[M], cost[M], nxt[M], head[N], tot = 1;

void add_edge(int u, int v, int w, int c) {
    to[++tot] = v; cap[tot] = w; cost[tot] = c; nxt[tot] = head[u]; head[u] = tot;
    to[++tot] = u; cap[tot] = 0; cost[tot] = -c; nxt[tot] = head[v]; head[v] = tot;
}

int s, t;
int dis[N], flow[N], pre[N], las[N];
bool inq[N];

bool spfa() {
    for(int i=1; i<=t; i++) dis[i] = INF, flow[i] = pre[i] = las[i] = 0, inq[i] = 0;
    queue<int> q;
    dis[s] = 0; flow[s] = INF; q.push(s); inq[s] = 1;
    while(!q.empty()) {
        int u = q.front(); q.pop(); inq[u] = 0;
        for(int i=head[u]; i; i=nxt[i]) {
            int v = to[i], w = cap[i], c = cost[i];
            if(w && dis[v] > dis[u] + c) {
                dis[v] = dis[u] + c;
                flow[v] = min(flow[u], w);
                pre[v] = u;
                las[v] = i;
                if(!inq[v]) {
                    q.push(v);
                    inq[v] = 1;
                }
            }
        }
    }
    return pre[t] != 0;
}

int max_flow, min_cost;
void mcmf() {
    while(spfa()) {
        int u = t, fl = flow[t];
        max_flow += fl;
        min_cost += fl * dis[t];
        while(u != s) {
            cap[las[u]] -= fl;
            cap[las[u]^1] += fl;
            u = pre[u];
        }
    }
}

