inline int read() {
    int x = 0, f = 1; char ch = getchar();
    while(!isdigit(ch)) { if(ch == '-') f = -1; ch = getchar(); }
    while(isdigit(ch)) { x = (x<<1) + (x<<3) + (ch^48); ch = getchar(); }
    return x * f;
}

void write(int x) {
    if(x < 0) { putchar('-'); x = -x; }
    if(x >= 10) write(x / 10);
    putchar(x % 10 + '0');
}

int main() {
    // freopen(".in", "r", stdin);
    // freopen(".out", "w", stdout);
    n = read(); m = read(); k = read(); c = read(); d = read();
    int B = n > k ? n : k;
    s = n * (B*2 + 1) + 1;
    t = s + 1;
    for(int i=0; i<k; i++) {
        int x = read();
        add_edge(s, x, 1, 0);
    }
