        int x = read(), y = read();
        for(int o=0; o<B*2; o++) {
            for(int i=1; i<=k; i++) {
                int w = d * (2*i - 1) + c;
                add_edge(o*n + x, (o+1)*n + y, 1, w);
                add_edge(o*n + y, (o+1)*n + x, 1, w);
            }
        }
    }
    mcmf();
    write(min_cost);
    putchar('\n');
    return 0;
}

