vector<int> head, to, cap, cost, nxt;
vector<int> dist, pre, preEdge, inq;

void addEdge(int u, int v, int flow, int c) {
    to.push_back(v);
    cap.push_back(flow);
    cost.push_back(c);
    nxt.push_back(head[u]);
    head[u] = (int)to.size() - 1;

    to.push_back(u);
    cap.push_back(0);
    cost.push_back(-c);
    nxt.push_back(head[v]);
    head[v] = (int)to.size() - 1;
}

bool spfa(int s, int t) {
    fill(dist.begin(), dist.end(), INF);
    fill(pre.begin(), pre.end(), -1);
    fill(inq.begin(), inq.end(), 0);
    queue<int> q;
    dist[s] = 0;
    q.push(s);
    inq[s] = 1;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        inq[u] = 0;
        for (int i = head[u]; ~i; i = nxt[i]) {
            int v = to[i];
            if (cap[i] > 0 && dist[v] > dist[u] + cost[i]) {
                dist[v] = dist[u] + cost[i];
                pre[v] = u;
                preEdge[v] = i;
                if (!inq[v]) {
                    inq[v] = 1;
                    q.push(v);
                }
            }
        }
    }
    return dist[t] < INF;
}

int minCostMaxFlow(int s, int t) {
    int result = 0;
    while (spfa(s, t)) {
        int add = INF;
        for (int v = t; v != s; v = pre[v]) {
            add = min(add, cap[preEdge[v]]);
        }
        for (int v = t; v != s; v = pre[v]) {
            int e = preEdge[v];
            cap[e] -= add;
            cap[e ^ 1] += add;
        }
        result += dist[t] * add;
    }
    return result;
}

int main() {
    int n, m, k, c, d;
    scanf("%d%d%d%d%d", &n, &m, &k, &c, &d);
    int s = 0, t = n * 100 + 1;
    int nodeCount = t + 1;

    head.assign(nodeCount, -1);
    dist.resize(nodeCount);
    pre.resize(nodeCount);
    preEdge.resize(nodeCount);
    inq.resize(nodeCount);

    for (int i = 1; i <= 100; ++i) addEdge(i, t, 100, 0);
    for (int i = 1; i <= k; ++i) {
        int v; scanf("%d", &v);
        addEdge(s, (v - 1) * 100 + 1, 1, 0);
    }
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j < 100; ++j) {
            addEdge((i - 1) * 100 + j, (i - 1) * 100 + j + 1, 100, c);
        }
    }
    for (int i = 1; i <= m; ++i) {
        int u, v; scanf("%d%d", &u, &v);
        for (int j = 1; j < 100; ++j) {
            int idx = (u - 1) * 100 + j;
            int idy = (v - 1) * 100 + j + 1;
            for (int p = 1; p <= 20; ++p) {
                addEdge(idx, idy, 1, c + (p * p - (p - 1) * (p - 1)) * d);
            }
            int idx2 = (v - 1) * 100 + j;
            int idy2 = (u - 1) * 100 + j + 1;
            for (int p = 1; p <= 20; ++p) {
                addEdge(idx2, idy2, 1, c + (p * p - (p - 1) * (p - 1)) * d);
            }
        }
    }

    printf("%d\n", minCostMaxFlow(s, t));
