#include<bits/stdc++.h>
using namespace std;
typedef long long ll;
typedef pair<int,int> pii;
typedef vector<int> vi;

const int INF = 1e9;
const int MAXN = 30000;
const int MAXM = 7010010;

struct Edge {
    int to, rev;
    int cap, cost;
};

struct MinCostFlow {
    int n;
    vector<vector<Edge>> g;
    vector<int> dist, prevv, preve;
    vector<int> potential;

    MinCostFlow(int _n) : n(_n), g(_n), dist(_n), prevv(_n), preve(_n), potential(_n, 0) {}

    void add_edge(int from, int to, int cap, int cost) {
        g[from].push_back({to, (int)g[to].size(), cap, cost});
        g[to].push_back({from, (int)g[from].size() - 1, 0, -cost});
    }

    int min_cost_flow(int s, int t, int maxf) {
        int flow = 0, cost = 0;
        while (flow < maxf) {
            fill(dist.begin(), dist.end(), INF);
            dist[s] = 0;
            priority_queue<pii, vector<pii>, greater<pii>> pq;
            pq.push({0, s});
            while (!pq.empty()) {
                auto [d, v] = pq.top(); pq.pop();
                if (dist[v] < d) continue;
                for (int i = 0; i < (int)g[v].size(); ++i) {
                    Edge &e = g[v][i];
                    if (e.cap > 0 && dist[e.to] > dist[v] + e.cost + potential[v] - potential[e.to]) {
                        dist[e.to] = dist[v] + e.cost + potential[v] - potential[e.to];
                        prevv[e.to] = v;
                        preve[e.to] = i;
                        pq.push({dist[e.to], e.to});
                    }
                }
            }
            if (dist[t] == INF) break;
            for (int v = 0; v < n; ++v) potential[v] += dist[v];
            int d = maxf - flow;
            for (int v = t; v != s; v = prevv[v]) d = min(d, g[prevv[v]][preve[v]].cap);
            flow += d;
            cost += d * potential[t];
            for (int v = t; v != s; v = prevv[v]) {
                Edge &e = g[prevv[v]][preve[v]];
                e.cap -= d;
                g[v][e.rev].cap += d;
            }
        }
        return cost;
    }
};

int n, m, k, c, d, a[55], id[55][2500];

int main() {
    scanf("%d%d%d%d%d", &n, &m, &k, &c, &d);
    for (int i = 1; i <= k; ++i) scanf("%d", &a[i]);

    int mx = 100;
    int cnt = 0;
    for (int i = 1; i <= n; ++i)
        for (int j = 0; j <= mx; ++j)
            id[i][j] = ++cnt;

    int total_nodes = cnt + 5;
    MinCostFlow mcf(total_nodes);
    int s = total_nodes - 2, t = total_nodes - 3;

    int u, v;
    for (int i = 1; i <= m; ++i) {
        scanf("%d%d", &u, &v);
        for (int j = 0; j < mx; ++j) {
            for (int h = 1; h <= k; ++h) {
                int tmp = h * h * d - (h - 1) * (h - 1) * d;
                mcf.add_edge(id[u][j], id[v][j + 1], 1, c + tmp);
                mcf.add_edge(id[v][j], id[u][j + 1], 1, c + tmp);
            }
        }
    }

    for (int i = 1; i <= n; ++i)
        for (int j = 0; j < mx; ++j)
            mcf.add_edge(id[i][j], id[i][j + 1], INF, c);

    for (int i = 1; i <= k; ++i)
        mcf.add_edge(s, id[a[i]][0], 1, 0);

    for (int j = 1; j <= mx; ++j)
        mcf.add_edge(id[1][j], t, INF, 0);

    int ans = mcf.min_cost_flow(s, t, k);
    printf("%d\n", ans);
    return 0;
}

