                        pv[e.to] = v;
                        pe[e.to] = i;
                        pq.push({d[e.to], e.to});
                    }
                }
            }
            if(d[t] == INF) break;
            for(int i=0;i<=n;i++) h[i] += d[i];
            int add = f;
            for(int v=t; v!=s; v=pv[v]) add = min(add, g[pv[v]][pe[v]].cap);
            f -= add; flow += add; ans += add * h[t];
            for(int v=t; v!=s; v=pv[v]) {
                Edge &e = g[pv[v]][pe[v]];
                e.cap -= add;
                g[v][e.rev].cap += add;
            }
        }
        return ans;
    }
} flow;

