template<typename flow_type, typename cost_type>
struct MinCostFlow
{
    struct Edge
    {
        int src, dst, rev;
        flow_type flow, cap;
        cost_type cost;
    };
    int N;
    vector<vector<Edge>> G;
    vector<cost_type> pot, dist;
    vector<Edge*> prev;
    const cost_type INF = numeric_limits<cost_type>::max();

    MinCostFlow(int n) : N(n), G(n), pot(n), dist(n), prev(n) {}

    void add_edge(int src, int dst, flow_type cap, cost_type cost)
    {
        G[src].push_back({src, dst, (int)G[dst].size(), 0, cap, cost});
        if (src == dst) G[src].back().rev++;
        G[dst].push_back({dst, src, (int)G[src].size() - 1, 0, 0, -cost});
    }

    cost_type reduced_cost(const Edge &e) const
    {
        return e.cost + pot[e.src] - pot[e.dst];
    }

    cost_type dijkstra(int s, int t)
    {
        fill(dist.begin(), dist.end(), INF);
        set<pair<cost_type, int>> pq;
        pq.insert({dist[s] = 0, s});
        while (!pq.empty())
        {
            auto it = pq.begin();
            cost_type d = it->first;
            int u = it->second;
            pq.erase(it);
            if (d != dist[u]) continue;
            if (u == t) break;
            for (Edge &e : G[u])
                if (e.flow < e.cap && dist[e.dst] > dist[e.src] + reduced_cost(e))
                {
                    pq.erase({dist[e.dst], e.dst});
                    dist[e.dst] = dist[e.src] + reduced_cost(e);
                    prev[e.dst] = &e;
                    pq.insert({dist[e.dst], e.dst});
                }
        }
        return dist[t];
    }

    pair<flow_type, cost_type> max_flow(int s, int t)
    {
        flow_type flow = 0;
        cost_type cost = 0;
        for (int u = 0; u < N; ++u)
            for (Edge &e : G[u])
                e.flow = 0;
        pot.assign(N, 0);
        dist.assign(N, 0);
        prev.assign(N, nullptr);
        while (dijkstra(s, t) < INF)
        {
            for (int u = 0; u < N; ++u)
                if (dist[u] < dist[t])
                    pot[u] += dist[u] - dist[t];
            flow_type f = numeric_limits<flow_type>::max();
            for (Edge *e = prev[t]; e; e = prev[e->src])
                f = min(f, e->cap - e->flow);
            for (Edge *e = prev[t]; e; e = prev[e->src])
            {
                e->flow += f;
                G[e->dst][e->rev].flow -= f;
            }
            flow += f;
            cost += f * (pot[t] - pot[s]);
        }
        return {flow, cost};
    }
};

