template<typename flow_type, typename cost_type>
struct MCMF
{
    struct Edge
    {
        int src, dst, rev;
        flow_type flow, cap;
        cost_type cost;
    };
    int N;
    vector<vector<Edge>> G;
    vector<cost_type> dist;
    vector<Edge*> prev;
    const cost_type INF = numeric_limits<cost_type>::max();

    MCMF(int n) : N(n), G(n), dist(n), prev(n) {}

    void add_edge(int src, int dst, flow_type cap, cost_type cost)
    {
        G[src].push_back({src, dst, (int)G[dst].size(), 0, cap, cost});
        if (src == dst) G[src].back().rev++;
        G[dst].push_back({dst, src, (int)G[src].size() - 1, 0, 0, -cost});
    }

    bool spfa(int s, int t)
    {
        fill(dist.begin(), dist.end(), INF);
        vector<bool> inq(N, false);
        queue<int> q;
        q.push(s);
        dist[s] = 0;
        inq[s] = true;
        while (!q.empty())
        {
            int u = q.front(); q.pop();
            inq[u] = false;
            for (Edge &e : G[u])
                if (e.flow < e.cap && dist[e.dst] > dist[e.src] + e.cost)
                {
                    dist[e.dst] = dist[e.src] + e.cost;
                    prev[e.dst] = &e;
                    if (!inq[e.dst])
                    {
                        q.push(e.dst);
                        inq[e.dst] = true;
                    }
                }
        }
        return dist[t] < INF;
    }

    pair<flow_type, cost_type> max_flow(int s, int t)
    {
        flow_type flow = 0;
        cost_type cost = 0;
        for (int u = 0; u < N; ++u)
            for (Edge &e : G[u])
                e.flow = 0;
        dist.assign(N, 0);
        prev.assign(N, nullptr);
        while (spfa(s, t))
        {
            flow_type f = numeric_limits<flow_type>::max();
            for (Edge *e = prev[t]; e; e = prev[e->src])
                f = min(f, e->cap - e->flow);
            for (Edge *e = prev[t]; e; e = prev[e->src])
            {
                e->flow += f;
                G[e->dst][e->rev].flow -= f;
            }
            flow += f;
            cost += f * dist[t];
        }
        return {flow, cost};
    }
};

