    edges[edges.size()-1].rev = edges.size()-2;
}

ll min_cost_flow(int s, int t, ll &price, int n) {
    vector<ll> potential(n, 0), dist(n);
    vector<int> prevv(n), preve(n);
    ll flow = 0;
    price = 0;
    while (true) {
        fill(dist.begin(), dist.end(), INF);
        dist[s] = 0;
        priority_queue<pair<ll,int>, vector<pair<ll,int>>, greater<pair<ll,int>>> pq;
        pq.push({0, s});
        while (!pq.empty()) {
            auto [d, v] = pq.top(); pq.pop();
            if (dist[v] < d) continue;
            for (int e = head[v]; e != -1; e = nxt[e]) {
                Edge &edge = edges[e];
                if (edge.cap > 0 && dist[edge.to] > dist[v] + edge.cost + potential[v] - potential[edge.to]) {
                    dist[edge.to] = dist[v] + edge.cost + potential[v] - potential[edge.to];
                    prevv[edge.to] = v;
                    preve[edge.to] = e;
                    pq.push({dist[edge.to], edge.to});
                }
            }
        }
        if (dist[t] == INF) break;
        for (int v = 0; v < n; ++v) potential[v] += dist[v];
        ll d = INF;
        for (int v = t; v != s; v = prevv[v]) {
            d = min(d, edges[preve[v]].cap);
        }
        flow += d;
        price += d * potential[t];
        for (int v = t; v != s; v = prevv[v]) {
            Edge &e = edges[preve[v]];
            e.cap -= d;
            edges[e.rev].cap += d;
        }
    }
    return flow;
}

