ll Dist[N], Pot[N];
int Parent[N];

void AddEdge(int u, int v, ll cap, ll cost) {
    Adj[u].push_back(Edges.size());
    Edges.push_back({u, v, cap, cost});
    Adj[v].push_back(Edges.size());
    Edges.push_back({v, u, 0, -cost});
}

void FordBellman(int s, int n) {
    fill(Pot, Pot + N, INF);
    Pot[s] = 0;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < (int)Edges.size(); j++) {
            Edge &e = Edges[j];
            if (e.cap == e.flow || Pot[e.from] == INF) continue;
            Pot[e.to] = min(Pot[e.to], Pot[e.from] + e.cost);
        }
    }
}

void Dijkstra(int s) {
    fill(Dist, Dist + N, INF);
    Dist[s] = 0;
    set<pair<ll, int>> Q;
    Q.insert({0, s});
    while (!Q.empty()) {
        int v = Q.begin()->second;
        Q.erase(Q.begin());
