const int MAX_NODES = MAX_N * MAX_T + 1;
const int MAX_EDGES = MAX_K + (MAX_M * 2 * MAX_K + MAX_N) * (MAX_T - 1);
const int INF = 0x3f3f3f3f;

struct Edge {
    int to, rev, cap, cost;
};

std::vector<Edge> graph[MAX_NODES];
int dist[MAX_NODES], h[MAX_NODES], prevv[MAX_NODES], preve[MAX_NODES];

void add_edge(int from, int to, int cap, int cost) {
    graph[from].push_back((Edge){to, (int)graph[to].size(), cap, cost});
    graph[to].push_back((Edge){from, (int)graph[from].size() - 1, 0, -cost});
}

int min_cost_flow(int s, int t, int f) {
    int res = 0;
    memset(h, 0, sizeof(h));
    while (f > 0) {
        std::priority_queue<std::pair<int, int>, std::vector<std::pair<int, int>>, std::greater<std::pair<int, int>>> pq;
        memset(dist, 0x3f, sizeof(dist));
        dist[s] = 0;
        pq.push({0, s});
        while (!pq.empty()) {
            auto p = pq.top(); pq.pop();
            int v = p.second;
            if (dist[v] < p.first) continue;
            for (int i = 0; i < (int)graph[v].size(); i++) {
                Edge &e = graph[v][i];
                if (e.cap > 0 && dist[e.to] > dist[v] + e.cost + h[v] - h[e.to]) {
                    dist[e.to] = dist[v] + e.cost + h[v] - h[e.to];
                    prevv[e.to] = v;
                    preve[e.to] = i;
                    pq.push({dist[e.to], e.to});
                }
            }
        }
        if (dist[t] == INF) return -1;
        for (int v = 0; v < MAX_NODES; v++) h[v] += dist[v];
        // Push as much flow as possible
        int d = f;
        for (int v = t; v != s; v = prevv[v]) {
            d = std::min(d, graph[prevv[v]][preve[v]].cap);
        }
        f -= d;
        res += d * h[t];
        for (int v = t; v != s; v = prevv[v]) {
            Edge &e = graph[prevv[v]][preve[v]];
            e.cap -= d;
            graph[v][e.rev].cap += d;
        }
    }
    return res;
}

