    vector<Edge> g[nn];
    void add_edge(int x, int y, int c, int w) {
        g[x].push_back({y, (int)g[y].size(), c, w});
        g[y].push_back({x, (int)g[x].size() - 1, 0, -w});
    }

    int dist[nn], h[nn]; // potentials
    int prex[nn], prei[nn];
    void dijkstra(int s) {
        memset(dist, 0x3f, sizeof dist);
        memset(prex, -1, sizeof prex);
        dist[s] = 0;
        priority_queue<pii, vector<pii>, greater<pii>> pq;
        pq.push(mp(0, s));
        while (!pq.empty()) {
            pii cur = pq.top(); pq.pop();
            int d = cur.first, x = cur.second;
            if (dist[x] < d) continue;
            for (int i = 0; i < (int)g[x].size(); ++i) {
                Edge &e = g[x][i];
                if (e.cap == 0) continue;
                int nd = d + e.cost + h[x] - h[e.to];
                if (dist[e.to] > nd) {
                    dist[e.to] = nd;
                    prex[e.to] = x;
                    prei[e.to] = i;
                    pq.push(mp(nd, e.to));
                }
            }
        }
    }

    int tot = 0;
    int dfs(int x, int flow) {
        if (prex[x] == -1) return flow;
        int y = x;
        x = prex[y];
        int i = prei[y];
        Edge &e = g[x][i];
        int f = dfs(x, min(flow, e.cap));
        e.cap -= f;
        g[y][e.rev].cap += f;
        return f;
    }

    pii solve(int s, int t) {
        int ans = 0;
        tot = 0;
        memset(h, 0, sizeof h);
        while (1) {
            dijkstra(s);
            if (dist[t] > 1e9) break;
            for (int i = 0; i < nn; ++i)
                if (dist[i] < 1e9) h[i] += dist[i];
            int f = dfs(t, inf);
            tot += f * h[t];
            ans += f;
        }
        return mp(ans, tot);
    }
};

