#include<bits/stdc++.h>
using namespace std;

const int maxn = 5005;
typedef int T;
const T INF = 1e9+7;
const int K = 100;

struct Edge {
    int  u , v ;
    T cap ,flow , cost;
};

struct MCMF {
    int n,m,s,t;      // Total Number of Node Including S,T
    vector<int> G[maxn];     //Graph
    vector<Edge> E;         // EdgeList
    T d[maxn];             // Distance Array of BeTmanFord
    bool inq[maxn];           // Is node in queue
    int p[maxn];
    T a[maxn];

    MCMF(int n) : n(n) {}

    void addEdge( int u , int v , T cap , T cost ){
//        cout<<u<<" "<<v<<" "<<cap<<"/"<<cost<<endl;
        E.push_back({u, v , cap , 0 , cost});       // Positive Cost
        E.push_back({v,u , 0, 0 , -cost } );        // Negative Cost
        m = (int) E.size();
        G[u].push_back(m - 2);
        G[v].push_back(m - 1);
    }

    bool BelmanFord(T &flow , T &cost ) {
        for(int i = 0; i < n ;i  ++) d[i] = INF ;
        memset(inq, 0, sizeof(inq));
        d[s] = 0; inq[s] = 1; p[s] = 0; a[s] = INF;

        queue<int> Q;
        Q.push(s);
        while(!Q.empty() ) {
            int u = Q.front(); Q.pop();
            inq[u] = 0;

            for( int i = 0 ; i < G[u].size() ; i ++ ) {
                Edge &e = E[G[u][i]];
                if( e.cap > e.flow && d[e.v] > d[u] + e.cost ) {
                    d[e.v] = d[u] + e.cost;
                    p[e.v] = G[u][i];
                    a[e.v] = min( a[u] , e.cap - e.flow );

                    if( inq[e.v ] == 0 ) {
                        Q.push(e.v);
                        inq[e.v] = 1;
                    }
                }
            }
        }

        if( d[t] == INF ) return false;     // No augmenting Path
        flow = a[t];
        cost = d[t] ;               // Unit cost
        int u = t ;
        while( u  != s ) {
            E[p[u]].flow += a[t];
            E[p[u]^1].flow -= a[t];
            u = E[p[u]].u;
        }
        return true;
    }

    pair<T,T> Mincost (int s, int t) {
        this->s=s,this->t=t;
        T Mcost = 0;
        T Flow = 0;
        T f = 0 ;    // For Each CaT , The flow
        T d = 0;      // Shortest Distance / Cost Per Flow

        while(BelmanFord(f,d)) {
            Flow += f;
            Mcost += f *d ;
        }
        return make_pair(Flow, Mcost);
    }
};

int main() {
    int n, m, k, C, D;
    cin>>n>>m>>k>>C>>D;

    MCMF solver(n*K+2);
    int source = n*K, sink = n*K+1;

    for (int i=0; i<K; i++)
        solver.addEdge(i, sink, k, C*i);


    for (int i=0; i<k; i++) {
        int x;
        cin>>x;
        x--;
        solver.addEdge(source, x*K, 1, 0);
    }

    for (int i=0; i<n; i++)
        for (int j=1; j<K; j++)
            solver.addEdge(i*K+j-1, i*K+j, k, 0);

    while (m--) {
        int u, v;
        cin>>u>>v;
        u--; v--;

        for (int j=1; j<K; j++) {
            int a = u*K+j-1, b = v*K+j;
            int c = v*K+j-1, d = u*K+j;

            for (int i=1, cc = D; i<=k; i++, cc += 2*D) {
                solver.addEdge(a, b, 1, cc);
                solver.addEdge(c, d, 1, cc);
            }
        }
    }
    auto pr = solver.Mincost(source, sink);
    cout<<pr.second<<endl;
}

#include <bits/stdc++.h>
using namespace std;

const int MAXN = 5005;
const int INF = 1000000007;
const int TIME = 100;
using CostType = int;

struct Arc {
    int from, to;
    CostType cap, flow, cost;
};

class MinCostFlow {
public:
    int n, m, S, T;
    vector<int> adj[MAXN];
    vector<Arc> edges;
    CostType dist[MAXN];
    bool inQueue[MAXN];
    int prev[MAXN];
    CostType possible[MAXN];

    MinCostFlow(int nodeCount) : n(nodeCount) {}

    void addEdge(int from, int to, CostType cap, CostType cost) {
        edges.push_back({from, to, cap, 0, cost});
        edges.push_back({to, from, 0, 0, -cost});
        m = (int)edges.size();
        adj[from].push_back(m - 2);
        adj[to].push_back(m - 1);
    }

    bool shortestPath(CostType &augFlow, CostType &pathCost) {
        for (int i = 0; i < n; ++i) dist[i] = INF;
        fill(inQueue, inQueue + n, false);

        dist[S] = 0;
        inQueue[S] = true;
        prev[S] = -1;
        possible[S] = INF;

        queue<int> q;
        q.push(S);

        while (!q.empty()) {
            int u = q.front();
            q.pop();
            inQueue[u] = false;

            for (int id : adj[u]) {
                Arc &e = edges[id];
                if (e.cap > e.flow && dist[e.to] > dist[u] + e.cost) {
                    dist[e.to] = dist[u] + e.cost;
                    prev[e.to] = id;
                    possible[e.to] = min(possible[u], e.cap - e.flow);
                    if (!inQueue[e.to]) {
                        q.push(e.to);
                        inQueue[e.to] = true;
                    }
                }
            }
        }

        if (dist[T] == INF) return false;

        augFlow = possible[T];
        pathCost = dist[T];

        for (int v = T; v != S; v = edges[prev[v]].from) {
            edges[prev[v]].flow += possible[T];
            edges[prev[v] ^ 1].flow -= possible[T];
        }
        return true;
    }

    pair<CostType, CostType> minCost(int s, int t) {
        S = s;
        T = t;
        CostType totalCost = 0;
        CostType totalFlow = 0;
        CostType f = 0, c = 0;

        while (shortestPath(f, c)) {
            totalFlow += f;
            totalCost += f * c;
        }
        return {totalFlow, totalCost};
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, k, C, D;
    cin >> n >> m >> k >> C >> D;

    MinCostFlow solver(n * TIME + 2);
    int src = n * TIME;
    int snk = src + 1;

    for (int t = 0; t < TIME; ++t) {
        solver.addEdge(t, snk, k, C * t);
    }

    for (int i = 0; i < k; ++i) {
        int x;
        cin >> x;
        --x;
        solver.addEdge(src, x * TIME, 1, 0);
    }

    for (int city = 0; city < n; ++city) {
        for (int t = 1; t < TIME; ++t) {
            solver.addEdge(city * TIME + t - 1, city * TIME + t, k, 0);
        }
    }

    while (m--) {
        int u, v;
        cin >> u >> v;
        --u; --v;

        for (int t = 1; t < TIME; ++t) {
            int a = u * TIME + t - 1, b = v * TIME + t;
            int c = v * TIME + t - 1, d = u * TIME + t;

            for (int i = 1, cost = D; i <= k; ++i, cost += 2 * D) {
                solver.addEdge(a, b, 1, cost);
                solver.addEdge(c, d, 1, cost);
            }
        }
    }

    auto ans = solver.minCost(src, snk);
    cout << ans.second << '\n';
    return 0;
}

