                int u = q.front(); q.pop();
                inq[u] = false;
                for (int i = 0; i < (int)G[u].size(); ++i) {
                    Edge &e = G[u][i];
                    if (e.cap > 0 && dist[e.to] > dist[u] + e.cost) {
                        dist[e.to] = dist[u] + e.cost;
                        pv[e.to] = u;
                        pe[e.to] = i;
                        if (!inq[e.to]) {
                            q.push(e.to);
                            inq[e.to] = true;
                        }
                    }
                }
            }

            if (dist[t] == INF) break;

            int add = INF;
            for (int v = t; v != s; v = pv[v]) {
                add = min(add, G[pv[v]][pe[v]].cap);
            }
            flow += add;
            cost += add * dist[t];
            for (int v = t; v != s; v = pv[v]) {
                Edge &e = G[pv[v]][pe[v]];
                e.cap -= add;
                G[v][e.rev].cap += add;
            }
        }
        return {flow, cost};
    }
};

