struct MCMF {
    int n, m, s, t;
    vector<int> G[MAXN];
    vector<Edge> E;
    int d[MAXN];
    int prev[MAXN];
    int aug[MAXN];

    MCMF(int n) : n(n) {}

    void addEdge(int u, int v, int cap, int cost) {
        E.push_back({u, v, cap, 0, cost});
        E.push_back({v, u, 0, 0, -cost});
        m = (int)E.size();
        G[u].push_back(m - 2);
        G[v].push_back(m - 1);
    }

    bool shortestPath(int &f, int &cost) {
        fill(d, d + n, INF);
        fill(aug, aug + n, INF);
        fill(prev, prev + n, -1);
        d[s] = 0;
        prev[s] = -1;
        aug[s] = INF;

        for (int iter = 0; iter < n - 1; ++iter) {
            bool any = false;
            for (int u = 0; u < n; ++u) {
                if (d[u] == INF) continue;
                for (int id : G[u]) {
                    Edge &e = E[id];
                    if (e.cap > e.flow && d[e.v] > d[u] + e.cost) {
                        d[e.v] = d[u] + e.cost;
                        prev[e.v] = id;
                        aug[e.v] = min(aug[u], e.cap - e.flow);
                        any = true;
                    }
                }
            }
            if (!any) break;
        }

        if (d[t] == INF) return false;

        f = aug[t];
        cost = d[t];
        for (int v = t; v != s; v = E[prev[v]].u) {
            E[prev[v]].flow += aug[t];
            E[prev[v] ^ 1].flow -= aug[t];
        }
        return true;
    }

    pair<int,int> minCost(int s, int t) {
        this->s = s;
        this->t = t;
        int totalFlow = 0;
        int totalCost = 0;
        int f, c;
        while (shortestPath(f, c)) {
            totalFlow += f;
            totalCost += f * c;
        }
        return {totalFlow, totalCost};
    }
};

