struct MinCostFlow {
    struct Edge {
        int to, capacity, flow, cost;
    };

    int S, T;
    vector<vector<int>> g;
    vector<Edge> edges;
    vector<ll> dist;
    vector<int> pred, predEdge;
    vector<char> inQueue;

    MinCostFlow(int nodes, int s, int t)
        : S(s), T(t), g(nodes), dist(nodes, INF),
          pred(nodes, -1), predEdge(nodes, -1), inQueue(nodes, 0) {}

    int residual(int id) const {
        return edges[id].capacity - edges[id].flow;
    }

    void addEdge(int u, int v, int capacity, int costValue) {
        g[u].push_back((int)edges.size());
        edges.push_back({v, capacity, 0, costValue});
        g[v].push_back((int)edges.size());
        edges.push_back({u, 0, 0, -costValue});
    }

    void augment() {
        fill(dist.begin(), dist.end(), INF);
        fill(pred.begin(), pred.end(), -1);
        fill(predEdge.begin(), predEdge.end(), -1);
        fill(inQueue.begin(), inQueue.end(), 0);

        deque<int> q;
        dist[S] = 0;
        q.push_back(S);
        inQueue[S] = 1;

        while (!q.empty()) {
            int u = q.front();
            q.pop_front();
            inQueue[u] = 0;

            for (int id : g[u]) {
                if (residual(id) == 0) continue;
                int v = edges[id].to;
