                    if (!inQueue[v]) {
                        inQueue[v] = 1;
                        q.push_back(v);
                    }
                }
            }
        }

        for (int cur = T; cur != S; cur = pred[cur]) {
            int id = predEdge[cur];
            edges[id].flow++;
            edges[id ^ 1].flow--;
        }
    }
};

