class MinCostFlow {
private:
    struct Edge {
        int y,c,v,ty;
        Edge(int _y=0,int _c=0,int _v=0,int ty=0):y(_y),c(_c),v(_v),ty(ty){}
    };
    vector<Edge> es;
    vector<vector<int>> e;
    int C, d, en, EE;
    vector<int> mi, lt, used;
    vector<int> bfs;

    int flow() {
        for (int i = 0; i <= EE; ++i) {
            mi[i] = INF;
            used[i] = 0;
        }
        mi[EE] = INF;
        bfs.clear();
        bfs.push_back(0);
        mi[0] = 0;
        int idx = 0;
        while (idx < (int)bfs.size()) {
            int x = bfs[idx++];
            used[x] = 0;
            for (int j = 0; j < (int)e[x].size(); ++j) {
                int r = e[x][j];
                if (es[r].c > 0 && mi[x] + es[r].v < mi[es[r].y]) {
                    mi[es[r].y] = mi[x] + es[r].v;
                    lt[es[r].y] = r;
                    if (!used[es[r].y]) {
                        used[es[r].y] = 1;
                        bfs.push_back(es[r].y);
                    }
                }
            }
        }
        if (mi[EE] == INF) return -1;
        int now = EE;
        while (now) {
            int r = lt[now];
            if (es[r].ty == 1) {
                es[r].v += 2 * d;
                es[r ^ 1].v -= 2 * d;
            }
            es[r].c--;
            es[r ^ 1].c++;
            now = es[r ^ 1].y;
        }
        return mi[EE];
    }

public:
    MinCostFlow(int max_nodes, int _C, int _d) : C(_C), d(_d) {
        e.resize(max_nodes + 1);
        mi.resize(max_nodes + 1);
        lt.resize(max_nodes + 1);
        used.resize(max_nodes + 1);
        clear(max_nodes);
    }

    void clear(int _EE) {
        EE = _EE;
        for (int i = 0; i <= EE; ++i) e[i].clear();
        es.clear();
        en = 0;
    }

    void add_edge(int x, int y, int c, int v, int _ty) {
        e[x].push_back(en);
        es.push_back(Edge(y, c, v, _ty));
        en++;
        e[y].push_back(en);
        if (_ty == 1) {
            es.push_back(Edge(x, 0, -C + d, _ty));
        } else {
            es.push_back(Edge(x, 0, -v, _ty));
        }
        en++;
    }

    int solve(int nn) {
        int v = 0;
        for (int i = 0; i < nn; ++i) v += flow();
        return v;
    }
};

int main() {
    int n, m, k, C, d;
    R(n, m, k, C, d);
    MinCostFlow mcf(n * 100 + 1, C, d);
    for (int i = 1; i <= k; ++i) {
        int x; R(x);
        mcf.add_edge(0, x, 1, 0, 0);
    }
    for (int i = 1; i <= 99; ++i) {
        mcf.add_edge(1 + i * n, 100 * n + 1, INF, 0, 0);
    }
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= 99; ++j) {
            mcf.add_edge(i + (j - 1) * n, i + j * n, INF, C, 0);
        }
    }
    for (int i = 1; i <= m; ++i) {
        int x, y; R(x, y);
        for (int j = 1; j <= 99; ++j) {
            mcf.add_edge(x + (j - 1) * n, y + j * n, INF, C + d, 1);
            mcf.add_edge(y + (j - 1) * n, x + j * n, INF, C + d, 1);
        }
    }
    W(mcf.solve(k));
    return 0;
}

