            ae(id(time, city), id(time + 1, city), INF, c);
            ae(id(time + 1, city), id(time, city), 0, -c);
        }
        for (int j = 1; j <= m; j++) {
            for (int k = 1; k <= p; k++) {
                int cost = d * k * k - d * (k - 1) * (k - 1) + c;
                ae(id(time, u[j]), id(time + 1, v[j]), 1, cost);
                ae(id(time + 1, v[j]), id(time, u[j]), 0, -cost);
                ae(id(time, v[j]), id(time + 1, u[j]), 1, cost);
                ae(id(time + 1, u[j]), id(time, v[j]), 0, -cost);
            }
        }
    }
    mcmf();
    cout << mnc << endl;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const int INF = 0x7f7f7f7f;
int N, M, S, T, P, C, D, A[505], B[505];
int MXF, MNC;
int E = 1, H[5000005], NX[5000005<<1], TO[5000005<<1], CAP[5000005<<1], COST[5000005<<1];
int DIS[5000005], PRE[5000005], LA[5000005], FLOW[5000005];
bool VIS[5000005];

void ADD(int X, int Y, int Z, int C) {
    NX[++E] = H[X];
    TO[E] = Y;
    CAP[E] = Z;
    COST[E] = C;
    H[X] = E;
}

bool SPFA() {
    fill(DIS, DIS + 5000005, INF);
    fill(VIS, VIS + 5000005, false);
    queue<int> Q;
    Q.push(S);
    VIS[S] = true;
    DIS[S] = 0;
    FLOW[S] = INF;
    PRE[T] = -1;
    while (!Q.empty()) {
        int X = Q.front(); Q.pop();
        VIS[X] = false;
        for (int I = H[X]; I; I = NX[I]) {
            if (CAP[I] && DIS[TO[I]] > DIS[X] + COST[I]) {
                DIS[TO[I]] = DIS[X] + COST[I];
                PRE[TO[I]] = X;
                LA[TO[I]] = I;
                FLOW[TO[I]] = min(FLOW[X], CAP[I]);
                if (!VIS[TO[I]]) {
                    VIS[TO[I]] = true;
                    Q.push(TO[I]);
                }
            }
        }
    }
    return PRE[T] != -1;
}

void MCMF() {
    MXF = MNC = 0;
    while (SPFA()) {
        int NOW = T;
        MXF += FLOW[T];
        MNC += FLOW[T] * DIS[T];
        while (NOW != S) {
            CAP[LA[NOW]] -= FLOW[T];
            CAP[LA[NOW] ^ 1] += FLOW[T];
            NOW = PRE[NOW];
        }
    }
}

int EN(int T, int X) {
    return T * N + X;
}

int main() {
    cin >> N >> M >> P >> C >> D;
    S = 0;
    T = N * 99 + 1;
    for (int I = 1, X; I <= P && cin >> X; I++) {
        ADD(S, EN(0, X), 1, 0);
        ADD(EN(0, X), S, 0, 0);
    }
    for (int I = 1; I <= M; I++) cin >> A[I] >> B[I];
    for (int I = 0; I <= 99; I++) {
        ADD(EN(I, 1), EN(I + 1, 1), INF, 0);
        ADD(EN(I + 1, 1), EN(I, 1), 0, 0);
        for (int J = 2; J <= N; J++) {
            ADD(EN(I, J), EN(I + 1, J), INF, C);
            ADD(EN(I + 1, J), EN(I, J), 0, -C);
        }
        for (int J = 1; J <= M; J++) {
            for (int K = 1; K <= P; K++) {
                int CST = D * K * K - D * (K - 1) * (K - 1) + C;
                ADD(EN(I, A[J]), EN(I + 1, B[J]), 1, CST);
                ADD(EN(I + 1, B[J]), EN(I, A[J]), 0, -CST);
                ADD(EN(I, B[J]), EN(I + 1, A[J]), 1, CST);
                ADD(EN(I + 1, A[J]), EN(I, B[J]), 0, -CST);
            }
        }
    }
    MCMF();
    cout << MNC << endl;
    return 0;
}

