int read_int() {
	int x = 0, sign = 1;
	char c = getchar();
	while (c < '0' || c > '9') {
		if (c == '-') sign = -1;
		c = getchar();
	}
	while (c >= '0' && c <= '9') {
		x = x * 10 + (c - '0');
		c = getchar();
	}
	return x * sign;
}

void write_int(int x) {
	if (x < 0) {
		putchar('-');
		x = -x;
	}
	char buf[12];
	int len = 0;
	do {
		buf[len++] = '0' + (x % 10);
		x /= 10;
	} while (x > 0);
	for (int i = len - 1; i >= 0; --i) putchar(buf[i]);
}

