    int p = lower_bound(a, a + n + 1, t) - a;
    int j = (p == 0 ? 0 : p - 1);

    int ans;
    if (a[i] - t < t - a[j] && a[i - 1] - t > a[i] - t)
        ans = a[i];
    else if (i - 1 >= 0 && a[i - 1] - t < t - a[j] && a[i - 1] - t < t - a[j])
        ans = a[i - 1];
    else
        ans = a[j];

    cout << ans;
    return 0;
}

