const double EPS = 1e-9;
const int MAXN = 20;

double inP[MAXN];
double p[MAXN];
double dp[1 << MAXN];
double sm[1 << MAXN];
double res[MAXN];
int id[MAXN];

void computeSum(int n) {
    sm[0] = 0.0;
    for (int mask = 1; mask < (1 << n); ++mask) {
        for (int j = 0; j < n; ++j) {
            if (mask & (1 << j)) {
                sm[mask] = sm[mask ^ (1 << j)] + p[j];
                break;
            }
        }
    }
}

void computeDp(int n) {
    dp[0] = 1.0;
    for (int mask = 0; mask < (1 << n); ++mask) {
        for (int i = 0; i < n; ++i) {
            if (mask & (1 << i)) continue;
            assert(p[i] > EPS);
            dp[mask | (1 << i)] += dp[mask] * p[i] / (1.0 - sm[mask]);
        }
    }
}

void gather(int n, int k) {
    for (int mask = 0; mask < (1 << n); ++mask) {
        int cnt = 0;
        for (int i = 0; i < n; ++i) cnt += (mask >> i) & 1;
        if (cnt != k) continue;
        for (int i = 0; i < n; ++i) {
            if (mask & (1 << i)) res[i] += dp[mask];
        }
    }
}

