                if (__builtin_popcount((unsigned)mask) != bits) continue;
                double sumP = 0.0;
                double sum = 0.0;
                for (int bit = 0; bit < m; ++bit) {
                    if (mask & (1 << bit)) {
                        sumP += p[bit];
                        sum += p[bit] * dp[mask ^ (1 << bit)];
                    }
                }
                dp[mask] = sum / (1.0 - sumP);
            }
        }

        double ans = dp[0];
        for (int mask = 1; mask < total; ++mask) {
            if (__builtin_popcount((unsigned)mask) < k) ans += dp[mask];
        }
        cout << ans << ' ';
    }
}

