void solve() {
    int n, k;
    cin >> n >> k;
    vector<double> allp(n);
    for (int i = 0; i < n; ++i) cin >> allp[i];

    for (int banned = 0; banned < n; ++banned) {
        double base = allp[banned];
        if (fabs(base) < 1e-6) {
            cout << "0 ";
            continue;
        }

        int m = n - 1;
        vector<double> p;
        p.reserve(m);
        for (int i = 0; i < n; ++i)
            if (i != banned) p.push_back(allp[i]);

        int total = 1 << m;
        vector<double> dp(total, 0.0);
        dp[0] = base;
        double ans = base;

        for (int mask = 1; mask < total; ++mask) {
            int temp = mask;
            double sumP = 0.0;
            double sum = 0.0;
            int cnt = 0;

            while (temp) {
                int bit = __builtin_ctz((unsigned)temp);
                sumP += p[bit];
                sum += p[bit] * dp[mask ^ (1 << bit)];
                ++cnt;
                temp &= temp - 1;
            }

            dp[mask] = sum / (1.0 - sumP);
            if (cnt < k) ans += dp[mask];
        }

        cout << ans << ' ';
    }
}

