        vector<ld> sumMask(total, 0.0);
        for (int mask = 1; mask < total; ++mask) {
            int b = __builtin_ctz((unsigned)mask);
            sumMask[mask] = sumMask[mask & (mask - 1)] + p[b];
        }

        vector<ld> dp(total, -1.0);
        vector<char> ready(total, 0);

        function<ld(int)> calc = [&](int mask) -> ld {
            if (ready[mask]) return dp[mask];
