class UnionFind {
private:
    vector<int> parent;
    vector<int> rnk;
public:
    UnionFind(int n) {
        parent.assign(n, 0);
        rnk.assign(n, 0);
        if (n > 0) {
            parent[0] = 0;
            rnk[0] = 0;
        }
        for (int i = 1; i < n; ++i) {
            parent[i] = i;
            rnk[i] = 1;
        }
    }

    int find(int x) {
        if (parent[x] != x)
            parent[x] = find(parent[x]);
        return parent[x];
    }

    void unite(int a, int b) {
        int ra = find(a);
        int rb = find(b);
        if (ra == rb) return;
        if (rnk[ra] >= rnk[rb]) {
            parent[rb] = ra;
            ++rnk[ra];
        } else {
            parent[ra] = rb;
            ++rnk[rb];
        }
    }
};

