int main() {
    int P, K;
    scanf("%d%d", &P, &K);

    vector<int> head(P, -1);
    vector<int> to(max(0, 2 * (P - 1)));
    vector<int> next(max(0, 2 * (P - 1)));
    int edgeCnt = 0;

    auto addEdge = [&](int u, int v) {
        to[edgeCnt] = v;
        next[edgeCnt] = head[u];
        head[u] = edgeCnt++;
    };

    for (int i = 1; i < P; ++i) {
        int j = (int)((long long)K * i % P);
        addEdge(i, j);
        addEdge(j, i);
    }

    vector<char> visited(P, 0);
    int relevantComponents = 0;

    for (int s = 0; s < P; ++s) {
        if (visited[s]) continue;

        bool containsNonZero = (s != 0);
        vector<int> st;
        st.push_back(s);
        visited[s] = 1;

        while (!st.empty()) {
            int u = st.back();
            st.pop_back();

            if (u != 0)
                containsNonZero = true;

            for (int e = head[u]; e != -1; e = next[e]) {
                int v = to[e];
                if (!visited[v]) {
                    visited[v] = 1;
                    st.push_back(v);
                }
            }
        }

        if (containsNonZero)
            ++relevantComponents;
    }

    long long ways;
    if (K == 0)
        ways = modPow(P, P - 1);
    else if (K == 1)
        ways = modPow(P, P);
    else
        ways = modPow(P, relevantComponents);

    printf("%lld\n", ways);
    return 0;
}

