using ll = long long;

struct DSU {
    vector<int> parent, sz;
    DSU(int n) : parent(n), sz(n, 1) {
        iota(parent.begin(), parent.end(), 0);
    }

    int find(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    void unite(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b) return;
        if (sz[a] < sz[b]) swap(a, b);
        parent[b] = a;
        sz[a] += sz[b];
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll p, k;
    cin >> p >> k;

    int n = (int)p;
    DSU dsu(n);

    for (ll i = 1; i < p; ++i) {
        ll r = (k * i) % p;
        if (r != 0) dsu.unite((int)r, (int)i);
    }

    vector<char> seen(n, 0);
    ll components = 0;
    for (ll i = 1; i < p; ++i) {
        int r = dsu.find((int)i);
        if (!seen[r]) {
            seen[r] = 1;
            ++components;
        }
    }

    if (k == 1) components = p;

    const ll MOD = 1000000007LL;
    ll ans = 1;
    for (ll i = 0; i < components; ++i) {
        ans = ans * p % MOD;
    }

    cout << ans << '\n';
    return 0;
}

