using ll = long long;
const ll MOD = 1000000007LL;

ll mod_pow(ll base, ll power, ll mod) {
  ll result = 1;
  while (power != 0) {
    if (power % 2 != 0) result = (result * base) % mod;
    base = (base * base) % mod;
    power /= 2;
  }
  return result;
}

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(nullptr);

  ll p, k;
  while (cin >> p >> k) {
    if (k == 0) {
