    if (k == 1) {
      cout << mod_pow(p, p, MOD) << '\n';
      continue;
    }

    vector<bool> visited(p, false);
    ll total = 0;

    for (ll start = 1; start < p; ++start) {
      if (visited[start]) continue;

      ll cur = start;
      ll len = 0;
      while (!visited[cur]) {
        ++len;
        visited[cur] = true;
        cur = (cur * k) % p;
      }

      if (mod_pow(k, len, p) == 1) ++total;
    }

    cout << mod_pow(p, total, MOD) << '\n';
  }

  return 0;
}

#include <bits/stdc++.h>
