#include <bits/stdc++.h>
using namespace std;

using ll = long long;
const ll MOD = 1000000007LL;

ll exp_mod(ll base, ll power, ll mod) {
  ll result = 1;
  while (power != 0) {
    if (power % 2 != 0) result = (result * base) % mod;
    base = (base * base) % mod;
    power /= 2;
  }
  return result;
}

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(nullptr);

  ll p, k;
  while (cin >> p >> k) {
    if (k == 0) {
      cout << exp_mod(p, p - 1, MOD) << '\n';
      continue;
    }
    if (k == 1) {
      cout << exp_mod(p, p, MOD) << '\n';
      continue;
    }

    vector<int> seen(p, 0);
    ll answer = 0;

    for (ll start = 1; start < p; ++start) {
      if (seen[start]) continue;

      vector<ll> stack;
      stack.push_back(start);
      ll steps = 0;

      while (!stack.empty()) {
        ll cur = stack.back();
        stack.pop_back();

        if (seen[cur]) continue;

        ++steps;
        seen[cur] = 1;

        ll nxt = (cur * k) % p;
        if (!seen[nxt]) stack.push_back(nxt);
      }

      if (exp_mod(k, steps, p) == 1) ++answer;
    }

    cout << exp_mod(p, answer, MOD) << '\n';
  }

  return 0;
}

