#include <bits/stdc++.h>
using namespace std;
using ll = long long;

const ll MOD = 1000000007LL;

ll pow_rec_impl(ll a, ll e, int bit, ll &acc) {
    if (bit < 0) return acc;
    acc = (acc * acc) % MOD;
    if ((e >> bit) & 1LL) acc = (acc * a) % MOD;
    return pow_rec_impl(a, e, bit - 1, acc);
}

ll pow_rec(ll a, ll e) {
    ll acc = 1;
    return pow_rec_impl(a, e, 30, acc);
}

