const int mod = 1e9 + 7;

int modpow(int x, int y) {
    long long res = 1;
    long long base = x % mod;
    while (y > 0) {
        if (y & 1) res = (res * base) % mod;
        base = (base * base) % mod;
        y >>= 1;
    }
    return (int)res;
}

