ll fpow(ll b, ll e) {
    ll result = 1;
    while (e > 0) {
        if (e & 1LL) {
            result *= b;
            result %= MOD;
        }
        b *= b;
        b %= MOD;
        e >>= 1;
    }
    return result;
}

ll multiplicative_order(ll p, ll k) {
    ll cnt = 1;
    ll now = k;
    for (;;) {
        if (now == 1) break;
        now = (now * k) % p;
        ++cnt;
    }
    return cnt;
}

