using namespace std;

const long long MOD = 1000000007LL;
const int MAXN = 2000005;

long long parent[MAXN];
long long sz[MAXN];

long long findNode(long long x) {
    while (parent[x] != x) {
        parent[x] = parent[parent[x]];
        x = parent[x];
    }
    return x;
}

void unite(long long a, long long b) {
    long long ra = findNode(a);
    long long rb = findNode(b);
    if (ra == rb) return;
    if (sz[ra] < sz[rb]) swap(ra, rb);
    parent[rb] = ra;
    sz[ra] += sz[rb];
}

long long recursivePow(long long x, long long e, long long M) {
    if (e == 0) return 1;
    if ((e & 1LL) == 0) {
        return recursivePow((x * x) % M, e / 2, M);
    } else {
        return (x * recursivePow((x * x) % M, (e - 1) / 2, M)) % M;
    }
}

