    }

    if (m == 0) {
        cout << modPow(n, n - 1) << '\n';
        return 0;
    }
    if (m == 1) {
        cout << modPow(n, n) << '\n';
        return 0;
    }

    for (long long i = 1; i < n; ++i) {
        long long bash = (i * m) % n;
        findunion(i, bash);
    }

