const long long MOD = 1000000007LL;

long long multiply_power(int p, long long exponent) {
    long long res = 1;
    for (long long cnt = 0; cnt < exponent; ++cnt) {
        res = (res * p) % MOD;
    }
    return res;
}

int main() {
    int p, k;
    cin >> p >> k;

    long long num;
    if (k <= 1) {
        num = multiply_power(p, (long long)p - 1 + k);
    } else {
        num = 1;
        vector<char> used(p, 0);
        for (int i = 1; i < p; ++i) {
            if (used[i]) continue;
            num = (num * p) % MOD;
            int q = i;
            do {
                used[q] = 1;
                q = (int)((long long)q * k % p);
            } while (q != i);
        }
    }

