const uint64_t Mod = 1000000007;

template<typename T>
static T FastPow(const T a, const T p)
{
    T res = 1;
    T base = a;
    T exp = p;
    while (exp)
    {
        if (exp & 1)
            res = (res * base) % Mod;
        base = (base * base) % Mod;
        exp >>= 1;
    }
    return res;
}

bool Solve(std::istream& ist, std::ostream& ost, const bool multipleTestMode)
{
    StopWatch<1> sw; (void)sw;

    uint64_t p, k;
    ist >> p >> k;

    if (multipleTestMode && !ist)
        return false;

    LOCAL_PRINT() << std::endl << "Next test: " << p << " " << k << std::endl;

    uint64_t ans;
    if (k == 0)
    {
        ans = FastPow(p, p - 1);
    }
    else if (k == 1)
    {
        ans = FastPow(p, p);
    }
    else
    {
        uint64_t groups = 0;
        std::vector<uint64_t> used(p + 1, 0);
        ans = 1;

        for (uint64_t x = 1; x < p; x++)
        {
            if (used[x])
                continue;

            groups++;
            ans = (ans * p) % Mod;

            used[x] = 1;
            uint64_t v = x;
            while (!used[v * k % p])
            {
                v = v * k % p;
                used[v] = 1;
            }
        }
    }

    ost << ans << std::endl;
    return multipleTestMode;
}

