#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
const ll MOD = 1000000007LL;

ll binpow(ll base, ll exp) {
    ll result = 1;
    for (; exp; exp >>= 1) {
        if (exp & 1) result = (result * base) % MOD;
        base = (base * base) % MOD;
    }
    return result;
}

ll orbit_length(ll p, ll k) {
    ll len = 1;
    ll cur = k % p;
    while (cur != 1) {
        cur = (cur * k) % p;
        ++len;
    }
    return len;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(NULL);

    ll p, k;
    cin >> p >> k;

    if (k == 0) {
        cout << binpow(p, p - 1) << '\n';
    } else if (k == 1) {
        cout << binpow(p, p) << '\n';
    } else {
        cout << binpow(p, (p - 1) / orbit_length(p, k)) << '\n';
    }

    return 0;
}

