#include <iostream>
#include <cstring>
using namespace std;
typedef long long ll;
const int MOD = 1000000007;
const int MAXN = 1000007;
ll P, K;
ll visited[MAXN];
ll cnt[MAXN];

ll calc(int len) {
    ll base = (cnt[len] * len) % MOD;
    base = (base + 1) % MOD;
    ll res = 1;
    for (int i = 1; i <= cnt[len]; i++)
        res = (res * base) % MOD;
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    cin >> P >> K;
    memset(visited, 0, sizeof(visited));
    memset(cnt, 0, sizeof(cnt));
    if (K == 0) {
        ll ans = 1;
        for (int i = 1; i < P; i++)
            ans = (ans * P) % MOD;
        cout << ans << "\n";
        return 0;
    }
    if (K == 1) {
        ll ans = 1;
        for (int i = 1; i <= P; i++)
            ans = (ans * P) % MOD;
        cout << ans << "\n";
        return 0;
    }
    for (int i = 0; i < P; i++) {
        if (!visited[i]) {
            ll len = 0;
            ll cur = i;
            while (!visited[cur]) {
                visited[cur] = 1;
                len++;
                cur = (K * cur) % P;
            }
            cnt[len]++;
        }
    }
    ll ans = 1;
    for (int i = 2; i < P; i++) {
        if (cnt[i]) {
            ans = (ans * calc(i)) % MOD;
        }
    }
    cout << ans << "\n";
    return 0;
}

#include <iostream>
#include <vector>
using namespace std;
using int64 = long long;
const int MOD = 1000000007;
const int MAXN = 1000007;
int64 P, K;
vector<int64> seen(MAXN, 0);
vector<int64> freq(MAXN, 0);

int64 power_mod(int64 base, int64 exp) {
    int64 result = 1;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return result;
}

int64 compute(int64 len) {
    int64 base = (freq[len] * len) % MOD;
    base = (base + 1) % MOD;
    return power_mod(base, freq[len]);
}

int main() {
    cin >> P >> K;
    if (K == 0) {
        cout << power_mod(P, P - 1) << "\n";
        return 0;
    }
    if (K == 1) {
        cout << power_mod(P, P) << "\n";
        return 0;
    }
    for (int i = 0; i < P; i++) {
        if (!seen[i]) {
            int64 len = 0;
            int64 cur = i;
            while (!seen[cur]) {
                seen[cur] = 1;
                len++;
                cur = (K * cur) % P;
            }
            freq[len]++;
        }
    }
    int64 ans = 1;
    for (int i = 2; i < P; i++) {
        if (freq[i]) {
            ans = (ans * compute(i)) % MOD;
        }
    }
    cout << ans << "\n";
    return 0;
}

#include <iostream>
#include <cstdlib>
using namespace std;
typedef long long ll;
const ll MOD = 1000000007LL;
const int MAXN = 1000007;
ll P, K;
ll mark[MAXN];
ll count_arr[MAXN];

ll fast_pow(ll base, ll exp) {
    ll result = 1;
    base %= MOD;
    while (exp) {
        if (exp & 1) result = (result * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return result;
}

ll helper(int len) {
    ll base = (count_arr[len] * len) % MOD;
    base = (base + 1) % MOD;
    return fast_pow(base, count_arr[len]);
}

int main() {
    cin >> P >> K;
    for (int i = 0; i < MAXN; i++) {
        mark[i] = 0;
        count_arr[i] = 0;
    }
    if (K == 0) {
        cout << fast_pow(P, P - 1) << "\n";
        return 0;
    }
    if (K == 1) {
        cout << fast_pow(P, P) << "\n";
        return 0;
    }
    for (int i = 0; i < P; i++) {
