vector<int> parent, compSize;

int findRoot(int v) {
    if (parent[v] == v) return v;
    return parent[v] = findRoot(parent[v]);
}

void unite(int a, int b) {
    a = findRoot(a);
    b = findRoot(b);
    if (a == b) return;
    if (compSize[a] < compSize[b]) {
        int t = a;
        a = b;
        b = t;
    }
    compSize[a] += compSize[b];
    parent[b] = a;
}

ll modPow(ll a, ll b) {
    ll res = 1;
    while (b) {
        if (b & 1) res = res * a % MOD;
        a = a * a % MOD;
        b >>= 1;
    }
    return res;
}

ll check(ll a, ll b, ll p) {
    ll res = 1;
    while (b) {
        if (b & 1) res = res * a % p;
        a = a * a % p;
        b >>= 1;
    }
    return (res == 1) ? p : 1;
}

