int findRoot(int v) {
    int root = v;
    while (parent[root] != root) root = parent[root];
    while (parent[v] != v) {
        int nxt = parent[v];
        parent[v] = root;
        v = nxt;
    }
    return root;
}

void unite(int a, int b) {
    a = findRoot(a);
    b = findRoot(b);
    if (a == b) return;
    if (rnk[a] < rnk[b]) {
        int t = a;
        a = b;
        b = t;
    }
    sz[a] += sz[b];
    parent[b] = a;
    if (rnk[a] == rnk[b]) rnk[a]++;
}

