#include <iostream>
#include <vector>
#include <algorithm>

int upperIndex(const std::vector<int>& values, int key) {
    int lo = 0;
    int hi = static_cast<int>(values.size());
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (values[mid] <= key)
            lo = mid + 1;
        else
            hi = mid;
    }
    return lo;
}

