{
	for (int i = 0; i < n; ++i)
	{
		for (int j = 0; j < n; ++j)
		{
			if (b[i][j] <= '0' || b[i][j] > '9') continue;
			ca.push_back(i);
			cb.push_back(j);
			int p = i*n+j;
			cap[p+2+n*n][1] = b[i][j]-'0';	
		}
	}
	int z = bi*n+bj;
	for (int i = 0; i < n; ++i)
	{
		for (int j = 0; j < n; ++j)
		{
			if (a[i][j] <= '0' || a[i][j] > '9') continue;
			int p = i*n+j;
			cap[0][p+2] = a[i][j]-'0';
			for (int k = 0; k < ca.size(); ++k)
			{
				int ii = ca[k];
				int jj = cb[k];
				int q = ii*n+jj;
				if (mat[p][q] < INF)
					cap[p+2][q+2+n*n] = INF;
			}
		}
	}
}

