#include <cstdio>
#include <cstring>
#include <vector>
#include <algorithm>
#include <queue>
using namespace std;

const int INF = 0x3f3f3f3f;
const int MAXN = 202;

class EdmondsKarp {
    int c[MAXN][MAXN], f[MAXN][MAXN];
    int N;
public:
    EdmondsKarp(int N_) : N(N_) {
        memset(c, 0, sizeof(c));
        memset(f, 0, sizeof(f));
    }
    void setCap(int u, int v, int val) { c[u][v] = val; }
    int maxflow(int s, int t) {
        while (true) {
            int pre[MAXN], d[MAXN];
            memset(pre, -1, sizeof(pre));
            queue<int> q;
            d[s] = INF;
            q.push(s);
            while (!q.empty() && pre[t] == -1) {
                int u = q.front(); q.pop();
                for (int v = 0; v < N; ++v) {
                    int r = c[u][v] - f[u][v];
                    if (pre[v] == -1 && r > 0) {
                        pre[v] = u;
                        d[v] = min(d[u], r);
                        q.push(v);
                    }
                }
            }
            if (pre[t] == -1) break;
            for (int v = t; v != s; v = pre[v]) {
                int u = pre[v];
                f[u][v] += d[t];
                f[v][u] -= d[t];
            }
        }
        int ans = 0;
        for (int i = 0; i < N; ++i) ans += f[s][i];
        return ans;
    }
};

int n, t, zi, zj;
char a[11][11], b[11][11];
int dir[4][2] = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};
vector<vector<int> > mat;

void bfs(int sr, int sc, bool prune) {
    int src = sr * n + sc;
    vector<int>& vis = mat[src];
    queue<pair<int, int> > q;
    vis[src] = 0;
    q.push(make_pair(sr, sc));
    while (!q.empty()) {
        pair<int, int> cur = q.front(); q.pop();
        int p = cur.first * n + cur.second;
        int dis = vis[p];
        if (prune && (mat[zi * n + zj][p] <= dis || t <= dis)) {
            if (mat[zi * n + zj][p] < dis || t < dis) vis[p] = INF + 1;
            continue;
        }
        for (int d = 0; d < 4; ++d) {
            int ni = cur.first + dir[d][0];
            int nj = cur.second + dir[d][1];
            if (ni < 0 || nj < 0 || ni == n || nj == n) continue;
            if (b[ni][nj] < '0' || b[ni][nj] > '9') continue;
            int nxt = ni * n + nj;
            if (vis[nxt] != INF) continue;
            vis[nxt] = dis + 1;
            q.push(make_pair(ni, nj));
        }
    }
}

void build(EdmondsKarp& ek) {
    vector<int> bcells;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (b[i][j] <= '0' || b[i][j] > '9') continue;
            int p = i * n + j;
            bcells.push_back(p);
            ek.setCap(p + 2 + n * n, 1, b[i][j] - '0');
        }
    }
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (a[i][j] <= '0' || a[i][j] > '9') continue;
            int p = i * n + j;
            ek.setCap(0, p + 2, a[i][j] - '0');
            for (int k = 0; k < (int)bcells.size(); ++k) {
                int q = bcells[k];
                if (mat[p][q] < INF) ek.setCap(p + 2, q + 2 + n * n, INF);
            }
        }
    }
}

int main() {
    scanf("%d%d", &n, &t);
    for (int i = 0; i < n; ++i) scanf("%s", a[i]);
    for (int i = 0; i < n; ++i) scanf("%s", b[i]);
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (a[i][j] == 'Z') zi = i, zj = j;

    mat.assign(n * n, vector<int>(n * n, INF));
    bfs(zi, zj, false);
    for (int i = 0; i < n; ++i)
