const int INF = 0x3f3f3f3f;

struct Edge {
    int to, rev, cap;
};

void addEdge(vector<vector<Edge> >& g, int u, int v, int c) {
    Edge a = {v, (int)g[v].size(), c};
    Edge b = {u, (int)g[u].size(), 0};
    g[u].push_back(a);
    g[v].push_back(b);
}

int maxFlow(vector<vector<Edge> >& g, int N, int s, int t) {
    int total = 0;
    while (true) {
        vector<int> parent(N, -1), parentEdge(N, -1), aug(N, 0);
        queue<int> q;
        parent[s] = s;
        aug[s] = INF;
        q.push(s);
        while (!q.empty() && parent[t] == -1) {
            int u = q.front(); q.pop();
            for (int i = 0; i < (int)g[u].size(); ++i) {
                Edge& e = g[u][i];
                if (parent[e.to] == -1 && e.cap > 0) {
                    parent[e.to] = u;
                    parentEdge[e.to] = i;
                    aug[e.to] = min(aug[u], e.cap);
                    q.push(e.to);
                }
            }
        }
        if (parent[t] == -1) break;
        int push = aug[t];
        for (int v = t; v != s; v = parent[v]) {
            Edge& e = g[parent[v]][parentEdge[v]];
            e.cap -= push;
            g[v][e.rev].cap += push;
        }
        total += push;
    }
    return total;
}

