			break;
		for (int i = 0; i <= counter; ++i)
		{
			if(flo[top][i] && parent[i]==-1)
			{
				parent[i]=top;
				dfs.push(i);
			}
		}
	}
	if(parent[counter]==-1)
		return 0;
