#include <bits/stdc++.h>
using namespace std;

int n, T, S;
int sc[10][10], tc[10][10], sn[10][10], tn[10][10];
int pl[10][10][61];
int f[250][250];
const int dr[4] = {0,0,-1,1};
const int dc[4] = {-1,1,0,0};

bool valid(int r, int c) {
    return 0 <= r && r < n && 0 <= c && c < n;
}

int edmondsKarp() {
    vector<int> par(S+1, -1);
    par[0] = 0;
    queue<int> q;
    q.push(0);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        if (u == S) break;
        for (int v = 0; v <= S; ++v) {
            if (f[u][v] > 0 && par[v] == -1) {
                par[v] = u;
                q.push(v);
            }
        }
    }
    if (par[S] == -1) return 0;
    int add = 10000;
    for (int v = S; v != 0; v = par[v]) add = min(add, f[par[v]][v]);
    for (int v = S; v != 0; v = par[v]) {
        f[par[v]][v] -= add;
        f[v][par[v]] += add;
    }
    return add;
}

