            if (g[i][j] == 'Y' || g[i][j] == 'Z') {
                pl[i][j][0] = g[i][j] - 'X';
                tc[i][j] = 0;
            } else {
                pl[i][j][0] = 0;
                tc[i][j] = g[i][j] - '0';
            }
        }

    for (int tm = 1; tm <= T; ++tm) {
        for (int i = 0; i < n; ++i)
