                if (pl[r][c][tm] != 0) continue;
                for (int k = 0; k < 4; ++k) {
                    int nr = r + dr[k], nc = c + dc[k];
                    if (valid(nr,nc) && pl[nr][nc][tm] == 0 && !vis[nr][nc]) {
                        vis[nr][nc] = true;
                        q.push({tm+1,{nr,nc}});
                    }
                }
