int dx[]={1,-1,0,0};
int dy[]={0,0,1,-1};

struct Edge {
    int to, rev;
    ll cap;
};

class Dinic {
public:
    vector<vector<Edge>> g;
    vector<int> level, it;
    int n, s, t;
    Dinic(int n, int s, int t) : n(n), s(s), t(t) {
        g.resize(n);
        level.resize(n);
        it.resize(n);
    }
    void add_edge(int from, int to, ll cap) {
        g[from].push_back({to, (int)g[to].size(), cap});
        g[to].push_back({from, (int)g[from].size()-1, 0});
    }
    bool bfs() {
        fill(level.begin(), level.end(), -1);
        queue<int> q;
        level[s] = 0;
        q.push(s);
        while (!q.empty()) {
            int v = q.front(); q.pop();
            for (auto &e : g[v]) {
                if (e.cap > 0 && level[e.to] < 0) {
                    level[e.to] = level[v] + 1;
                    q.push(e.to);
                }
            }
        }
        return level[t] >= 0;
    }
    ll dfs(int v, ll f) {
        if (v == t) return f;
        for (int &i = it[v]; i < (int)g[v].size(); ++i) {
            Edge &e = g[v][i];
            if (e.cap > 0 && level[v] < level[e.to]) {
                ll d = dfs(e.to, min(f, e.cap));
                if (d > 0) {
                    e.cap -= d;
                    g[e.to][e.rev].cap += d;
                    return d;
                }
            }
        }
        return 0;
    }
    ll max_flow() {
        ll flow = 0;
        while (bfs()) {
            fill(it.begin(), it.end(), 0);
            ll f;
            while ((f = dfs(s, 1e18)) > 0) flow += f;
        }
        return flow;
    }
};

