int max_flow(int s, int t) {
    int total = 0;
    const int INF = 1e9;
    while (true) {
        for (int i = vn; i--;) from[i] = -1;
        from[s] = s;
        flow[s] = INF;
        queue<int> bfs;
        bfs.push(s);
        bool found = false;
        while (!bfs.empty()) {
            int x = bfs.front(); bfs.pop();
            if (x == t) {
                found = true;
                int aug = flow[t];
                for (int v = t; v != s; v = from[v]) {
                    int u = from[v];
                    edge[u][v] -= aug;
                    edge[v][u] += aug;
                }
                total += aug;
                break;
            }
            for (auto &e : edge[x]) {
                if (e.second > 0 && from[e.first] == -1) {
                    from[e.first] = x;
                    flow[e.first] = min(e.second, flow[x]);
                    bfs.push(e.first);
                }
            }
        }
        if (!found) break;
    }
    return total;
}

