struct Matcher {
    static const int MAXN = 2000;
    int ans, leftMatch[MAXN], rightMatch[MAXN], used[MAXN];

    int run(int n, vector<int> g[]) {
        ans = 0;
        memset(leftMatch, 255, sizeof(leftMatch));
        memset(rightMatch, 255, sizeof(rightMatch));
        for (int i = 0; i < n; ++i) {
            memset(used, 0, sizeof(used));
            if (augment(i, g)) ++ans;
        }
        return ans;
    }

    bool augment(int x, vector<int> g[]) {
        for (int i = 0; i < (int)g[x].size(); ++i) {
            int y = g[x][i];
            if (used[y]) continue;
            used[y] = 1;
            if (rightMatch[y] == -1 || augment(rightMatch[y], g)) {
                leftMatch[x] = y;
                rightMatch[y] = x;
                return true;
            }
        }
        return false;
    }
};

