        int c = q.front().second;
        q.pop();
        for (int k = 0; k < 4; ++k) {
            int nr = r + dr[k];
            int nc = c + dc[k];
            if (A[nr][nc] >= 0 && F[nr][nc] < 0) {
                F[nr][nc] = F[r][c] + 1;
                q.push(make_pair(nr, nc));
            }
        }
    }
}

void linkMonsters(int sr, int sc, int cnt) {
    int seen[12][12];
    queue<pair<int, int> > q;
    memset(seen, 255, sizeof(seen));
    seen[sr][sc] = 0;
    q.push(make_pair(sr, sc));
    while (!q.empty()) {
        int r = q.front().first;
        int c = q.front().second;
        q.pop();
        int limit = min(T, F[r][c]);
        if (seen[r][c] > limit) continue;
        for (int i = 0; i < (int)objects[r][c].size(); ++i)
            for (int k = 0; k < cnt; ++k)
                graph[monsters + k].push_back(objects[r][c][i]);
        if (seen[r][c] == limit) continue;
        for (int k = 0; k < 4; ++k) {
            int nr = r + dr[k];
            int nc = c + dc[k];
            if (A[nr][nc] >= 0 && seen[nr][nc] < 0) {
                seen[nr][nc] = seen[r][c] + 1;
                q.push(make_pair(nr, nc));
            }
        }
    }
    monsters += cnt;
}

