bool findLevel() {
    fill(level.begin(), level.end(), -1);
    queue<int> q;
    level[src] = 0;
    q.push(src);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int id : G[u]) {
            int v = E[id].v;
            if (level[v] == -1 && E[id].flow < E[id].capacity) {
                level[v] = level[u] + 1;
                q.push(v);
                if (v == sink) return true;
            }
        }
    }
    return false;
}

long long blockFlow(int u, int f) {
    if (f == 0) return 0;
    if (u == sink) return f;
    for (int &i = nextEdge[u]; i < (int)G[u].size(); ++i) {
        int id = G[u][i];
