#include <bits/stdc++.h>
using namespace std;

const int MAXN = 12;
const int INF = 1000000;
const int MAXNODE = 205;

int N, T;
char firstGrid[MAXN][MAXN], secondGrid[MAXN][MAXN];
int distFromZ[MAXN][MAXN];
int canFlow[MAXN][MAXN][MAXN][MAXN];

int dr[4] = {-1,1,0,0};
int dc[4] = {0,0,-1,1};

struct Edge {
    int from, to, capacity, flow;
};

int nodeCount, source, sink;
int level[MAXNODE], nextEdge[MAXNODE], queueArr[MAXNODE];
vector<Edge> edges;
vector<int> adj[MAXNODE];

void addEdge(int from, int to, int capacity) {
    edges.push_back({from, to, capacity, 0});
    adj[from].push_back((int)edges.size() - 1);
    edges.push_back({to, from, 0, 0});
    adj[to].push_back((int)edges.size() - 1);
}

bool makeLevelGraph() {
    int head = 0, tail = 0;
    queueArr[tail++] = source;
    memset(level, -1, nodeCount * sizeof(level[0]));
    level[source] = 0;
    while (head < tail && level[sink] == -1) {
        int v = queueArr[head++];
        for (int id : adj[v]) {
            int to = edges[id].to;
            if (level[to] == -1 && edges[id].flow < edges[id].capacity) {
                queueArr[tail++] = to;
                level[to] = level[v] + 1;
            }
        }
    }
    return level[sink] != -1;
}

int sendFlow(int v, int pushed) {
    if (pushed == 0) return 0;
    if (v == sink) return pushed;
    for (int &i = nextEdge[v]; i < (int)adj[v].size(); ++i) {
        int id = adj[v][i];
        int to = edges[id].to;
        if (level[to] != level[v] + 1) continue;
        int got = sendFlow(to, min(pushed, edges[id].capacity - edges[id].flow));
        if (got) {
            edges[id].flow += got;
            edges[id ^ 1].flow -= got;
            return got;
        }
    }
    return 0;
}

int maxFlow() {
    int answer = 0;
    while (makeLevelGraph()) {
        memset(nextEdge, 0, nodeCount * sizeof(nextEdge[0]));
        while (int pushed = sendFlow(source, INF))
            answer += pushed;
    }
    return answer;
}

bool reachableInTime(int sx, int sy, int tx, int ty) {
    if (firstGrid[sx][sy] == 'Y' || firstGrid[sx][sy] == 'Z' ||
        firstGrid[tx][ty] == 'Y' || firstGrid[tx][ty] == 'Z')
        return false;

    int dist[MAXN][MAXN];
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j)
            dist[i][j] = INF;

    queue<pair<int,int>> q;
    dist[sx][sy] = 0;
    q.push({sx, sy});

    while (!q.empty()) {
        int x = q.front().first;
        int y = q.front().second;
        q.pop();

        if (x == tx && y == ty) return true;

        if (dist[x][y] >= T || dist[x][y] >= distFromZ[x][y])
            continue;

        for (int d = 0; d < 4; ++d) {
            int nx = x + dr[d], ny = y + dc[d];
            if (nx >= 0 && nx < N && ny >= 0 && ny < N &&
                firstGrid[nx][ny] != 'Y' && firstGrid[nx][ny] != 'Z' &&
                dist[nx][ny] == INF &&
                dist[x][y] + 1 <= distFromZ[nx][ny]) {
                dist[nx][ny] = dist[x][y] + 1;
                q.push({nx, ny});
            }
        }
    }
    return false;
}

int main() {
    scanf("%d%d", &N, &T);
    for (int i = 0; i < N; ++i) scanf("%s", firstGrid[i]);
    getchar();
    for (int i = 0; i < N; ++i) scanf("%s", secondGrid[i]);

    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j)
            distFromZ[i][j] = INF;

    queue<pair<int,int>> q;
    for (int x = 0; x < N; ++x)
        for (int y = 0; y < N; ++y)
            if (firstGrid[x][y] == 'Z') {
                for (int d = 0; d < 4; ++d) {
                    int nx = x + dr[d], ny = y + dc[d];
                    if (nx >= 0 && nx < N && ny >= 0 && ny < N &&
                        firstGrid[nx][ny] != 'Y') {
                        distFromZ[nx][ny] = 1;
                        q.push({nx, ny});
                    }
                }
            }

    while (!q.empty()) {
        int x = q.front().first, y = q.front().second;
        q.pop();
        for (int d = 0; d < 4; ++d) {
            int nx = x + dr[d], ny = y + dc[d];
            if (nx >= 0 && nx < N && ny >= 0 && ny < N &&
                firstGrid[nx][ny] != 'Y' && firstGrid[nx][ny] != 'Z' &&
                distFromZ[nx][ny] == INF) {
                distFromZ[nx][ny] = distFromZ[x][y] + 1;
                q.push({nx, ny});
            }
        }
    }

    for (int x1 = 0; x1 < N; ++x1)
        for (int y1 = 0; y1 < N; ++y1)
            for (int x2 = 0; x2 < N; ++x2)
                for (int y2 = 0; y2 < N; ++y2)
                    canFlow[x1][y1][x2][y2] = reachableInTime(x1, y1, x2, y2) ? 1 : 0;

    source = 0;
    sink = 2 * N * N + 1;
    nodeCount = 2 * N * N + 2;

    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j) {
            if (firstGrid[i][j] > '0' && firstGrid[i][j] <= '9')
                addEdge(source, 1 + i * N + j, firstGrid[i][j] - '0');
            if (secondGrid[i][j] > '0' && secondGrid[i][j] <= '9')
                addEdge(N * N + 1 + i * N + j, sink, secondGrid[i][j] - '0');
        }

    for (int x1 = 0; x1 < N; ++x1)
        for (int y1 = 0; y1 < N; ++y1)
            for (int x2 = 0; x2 < N; ++x2)
                for (int y2 = 0; y2 < N; ++y2)
                    if (canFlow[x1][y1][x2][y2])
                        addEdge(1 + x1 * N + y1, N * N + 1 + x2 * N + y2, INF);

    printf("%d\n", maxFlow());
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int MAXN = 12;
const int INF = 1000000;
const int MAXNODE = 205;

int N, T;
char g1[MAXN][MAXN], g2[MAXN][MAXN];
int zdist[MAXN][MAXN];
int okPair[MAXN][MAXN][MAXN][MAXN];

int dirX[4] = {-1,1,0,0};
int dirY[4] = {0,0,-1,1};

struct NetEdge { int a,b,c,f; };

int totNodes, src, snk;
int lvl[MAXNODE], it[MAXNODE], qarr[MAXNODE];
vector<NetEdge> E;
vector<int> G[MAXNODE];

void addEdge(int a,int b,int c) {
    E.push_back({a,b,c,0});
    G[a].push_back((int)E.size()-1);
    E.push_back({b,a,0,0});
    G[b].push_back((int)E.size()-1);
}

bool bfsLevel() {
    int h=0,t=0;
    qarr[t++]=src;
    memset(lvl,-1,totNodes*sizeof(lvl[0]));
    lvl[src]=0;
    while (h<t && lvl[snk]==-1) {
        int v=qarr[h++];
        for (int id : G[v]) {
            int w=E[id].b;
            if (lvl[w]==-1 && E[id].f < E[id].c) {
                qarr[t++]=w;
                lvl[w]=lvl[v]+1;
            }
        }
    }
    return lvl[snk]!=-1;
}

int augment(int v,int pushed) {
    if (!pushed) return 0;
    if (v==snk) return pushed;
    for (int &i=it[v]; i<(int)G[v].size(); ++i) {
        int id=G[v][i], w=E[id].b;
        if (lvl[w]!=lvl[v]+1) continue;
        int got=augment(w, min(pushed, E[id].c-E[id].f));
        if (got) {
            E[id].f += got;
            E[id^1].f -= got;
            return got;
        }
    }
    return 0;
}

int dinic() {
    int ans=0;
    while (bfsLevel()) {
        memset(it,0,totNodes*sizeof(it[0]));
        while (int pushed=augment(src,INF)) ans += pushed;
    }
    return ans;
}

bool canTravel(int sx,int sy,int tx,int ty) {
    if (g1[sx][sy]=='Y' || g1[sx][sy]=='Z' || g1[tx][ty]=='Y' || g1[tx][ty]=='Z')
        return false;
    int dist[MAXN*MAXN];
    for (int i=0;i<N*N;++i) dist[i]=INF;
    deque<int> dq;
    int start = sx*N+sy;
    dist[start]=0;
    dq.push_back(start);
    while (!dq.empty()) {
        int v = dq.front(); dq.pop_front();
        int x = v/N, y = v%N;
        if (x==tx && y==ty) return true;
        if (dist[v] >= T || dist[v] >= zdist[x][y]) continue;
        for (int d=0; d<4; ++d) {
            int nx=x+dirX[d], ny=y+dirY[d];
            if (nx<0||nx>=N||ny<0||ny>=N) continue;
            if (g1[nx][ny]=='Y'||g1[nx][ny]=='Z') continue;
            int nid=nx*N+ny;
            if (dist[nid]==INF && dist[v]+1 <= zdist[nx][ny]) {
                dist[nid]=dist[v]+1;
                dq.push_back(nid);
            }
        }
    }
    return false;
}

int main() {
    scanf("%d%d",&N,&T);
    for(int i=0;i<N;i++) scanf("%s",g1[i]);
    getchar();
    for(int i=0;i<N;i++) scanf("%s",g2[i]);

    for(int i=0;i<N;i++)
        for(int j=0;j<N;j++)
            zdist[i][j]=INF;

