    i = start.x; j = start.y;
    distB[i][j] = 0;
    q.push(start);
    while (!q.empty()) {
        temp = q.front(); q.pop();
        i = temp.x; j = temp.y;
        if (distB[i][j] > limit) continue;
        if (gridA[i][j] == 'Y') continue;
