int augment(int v, int t, int f, int n, vector<vector<int> >& cap, vector<int>& used) {
    if (v == t) return f;
    used[v] = 1;
    for (int u = 0; u < n; ++u) {
        if (used[u] || cap[v][u] <= 0) continue;
        int got = augment(u, t, min(f, cap[v][u]), n, cap, used);
        if (got > 0) {
            cap[v][u] -= got;
            cap[u][v] += got;
            return got;
        }
    }
    return 0;
}

int maxflow(int s, int t, vector<vector<int> > cap) {
    int n = (int)cap.size();
    int total = 0;
    while (true) {
        vector<int> used(n, 0);
        int f = augment(s, t, INT_MAX, n, cap, used);
        if (f == 0) break;
        total += f;
    }
    return total;
}

