inline int idx(int r, int c) { return r * W + c; }

void bfs_from_z(const Pos& z) {
    D1.assign(W * W, -1);
    vector<int> q;
    q.reserve(W * W);
    int head = 0;
    D1[idx(z.r, z.c)] = 0;
    q.push_back(idx(z.r, z.c));
    while (head < (int)q.size()) {
        int cur = q[head++];
        int r = cur / W, c = cur % W;
        for (int k = 0; k < 4; ++k) {
            int nr = r + dr[k], nc = c + dc[k];
            if (B[nr][nc] != '.') continue;
            int ni = idx(nr, nc);
            if (D1[ni] != -1) continue;
            D1[ni] = D1[cur] + 1;
            q.push_back(ni);
        }
    }
}

void bfs_from_scientist(const Pos& s) {
