}

int max_flow(int s, int t, vector<vector<int> > cap) {
    int n = (int)cap.size();
    int flow = 0;
    while (true) {
        vector<int> pre(n, -1);
        vector<int> q;
        q.reserve(n);
        int head = 0;
        pre[s] = s;
        q.push_back(s);
        while (head < (int)q.size() && pre[t] == -1) {
            int u = q[head++];
            for (int v = 0; v < n; ++v) {
                if (pre[v] == -1 && cap[u][v] > 0) {
                    pre[v] = u;
                    q.push_back(v);
                    if (v == t) break;
                }
            }
        }
        if (pre[t] == -1) break;
        int add = INT_MAX;
        for (int v = t; v != s; v = pre[v])
            add = min(add, cap[pre[v]][v]);
        for (int v = t; v != s; v = pre[v]) {
            cap[pre[v]][v] -= add;
            cap[v][pre[v]] += add;
        }
        flow += add;
    }
    return flow;
}

