bool findPath() {
    memset(visited, false, sizeof(visited));
    memset(parent, 0, sizeof(parent));
    queue<int> q;
    visited[0] = true;
    q.push(0);
    while (!q.empty()) {
        int v = q.front(); q.pop();
        if (v == 2 * n * n + 1) return true;
        for (int u = 0; u <= 2 * n * n + 1; ++u) {
            if (cap[v][u] > 0 && !visited[u]) {
                visited[u] = true;
                parent[u] = v;
                q.push(u);
            }
        }
    }
    return false;
}

void solve() {
    scanf("%d%d", &n, &t);
