    computeDist(sx, sy);

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (isdigit(a[i][j]))
                dp[0][i][j][i][j] = true;

    for (int time = 0; time < t; ++time) {
        for (int s1 = 0; s1 < n; ++s1)
            for (int s2 = 0; s2 < n; ++s2)
