void buildGraph() {
    N = n * n;
    memset(graph, -1, sizeof(graph));
    for (int r = 1; r <= n; ++r) {
        for (int c = 1; c <= n; ++c) {
            if (grid[r][c] == -1) continue;
            int p = (r-1)*n + c;
            graph[p][p] = 0;
            for (int d = 0; d < 4; ++d) {
                int nr = r + dirs[d][0];
                int nc = c + dirs[d][1];
                if (nr > 0 && nr <= n && nc > 0 && nc <= n && grid[nr][nc] != -1) {
                    int np = (nr-1)*n + nc;
                    graph[p][np] = 1;
                }
