            int pushed = sendFlow(y, min(rem, edges[i].cap - edges[i].flow));
            if (!pushed) depth[y] = 0;
            edges[i].flow += pushed;
            edges[i ^ 1].flow -= pushed;
            rem -= pushed;
            if (rem == 0) break;
        }
    }
    return now - rem;
}

