int dfs(int u,int sink,int f) {
    if (u == sink) return f;
    if (visited[u]) return 0;
    visited[u] = true;
    for (int v=0; v<=sink; ++v) {
        if (cap[u][v] > 0) {
            int got = dfs(v, sink, min(f, cap[u][v]));
            if (got) {
                cap[u][v] -= got;
                cap[v][u] += got;
                return got;
            }
        }
    }
    return 0;
}

int try_augment(int src,int sink,int f) {
    memset(visited,0,sizeof(visited));
    return dfs(src,sink,f);
}

