#include <cstdio>
#include <cstring>
#include <queue>
#include <cctype>
#include <vector>
#include <algorithm>
#define INF 1000000000
using namespace std;

class MaxFlow {
	vector<vector<int> > cap, flow;
	vector<int> parent;
	vector<char> seen;
	int n, s, t;

public:
	void init(int n, int s, int t) {
		this->n = n;
		this->s = s;
		this->t = t;
		cap.assign(n, vector<int>(n, 0));
		flow.assign(n, vector<int>(n, 0));
		parent.resize(n);
		seen.resize(n);
	}

	void addEdge(int u, int v, int c) {
		cap[u][v] += c;
	}

	int maxFlow() {
		int ret = 0;
		while(true) {
			fill(seen.begin(), seen.end(), 0);
			queue<int> q;
			q.push(s);
			seen[s] = 1;
			parent[s] = -1;

			while(!q.empty()) {
				int u = q.front();
				q.pop();
				for(int v = 0; v < n; ++v) {
					if(!seen[v] && cap[u][v] - flow[u][v] > 0) {
						seen[v] = 1;
						parent[v] = u;
						if(v == t)
							break;
						q.push(v);
					}
				}
				if(seen[t])
					break;
			}

			if(!seen[t])
				break;

			int add = INF;
			for(int v = t; v != s; v = parent[v])
				add = min(add, cap[parent[v]][v] - flow[parent[v]][v]);

			for(int v = t; v != s; v = parent[v]) {
				flow[parent[v]][v] += add;
				flow[v][parent[v]] -= add;
			}

			ret += add;
		}
		return ret;
	}
} mf;

