            cur[v] = head[v];
            q.push(v);
            if (v == t) return true;
        }
    }
    return false;
}

int dfs(int x, int t, int flow) {
    if (x == t) return flow;
    int rest = flow;
    for (int &i = cur[x]; i != -1 && rest; i = edge[i].next) {
        int v = edge[i].to;
        int w = edge[i].w;
        if (w && level[v] == level[x] + 1) {
            int k = dfs(v, t, min(rest, w));
            if (!k) level[v] = 0;
            edge[i].w -= k;
            edge[i ^ 1].w += k;
            rest -= k;
        }
    }
    return flow - rest;
}

