// Edmonds-Karp max flow
int parent[MAXN];
bool ekBfs(int s, int t) {
    memset(parent, -1, sizeof(parent));
    queue<int> q;
    q.push(s);
    parent[s] = -2;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int i = head[u]; i != -1; i = edge[i].next) {
            int v = edge[i].to;
            int w = edge[i].w;
            if (parent[v] == -1 && w > 0) {
                parent[v] = i;
                q.push(v);
                if (v == t) return true;
            }
        }
    }
    return false;
}

int edmondsKarp(int s, int t) {
    int flow = 0;
    while (ekBfs(s, t)) {
        int f = INF;
        for (int v = t; v != s; v = edge[parent[v] ^ 1].to) {
            int i = parent[v];
            f = min(f, edge[i].w);
        }
        for (int v = t; v != s; v = edge[parent[v] ^ 1].to) {
            int i = parent[v];
            edge[i].w -= f;
            edge[i ^ 1].w += f;
        }
        flow += f;
    }
    return flow;
}

