    {
        int v=l.front().first,x=l.front().second.first,y=l.front().second.second;
        l.pop();
        h[x][y]=v;
        if (x>0 && m[x-1][y] && h[x-1][y]>h[x][y]+1 && (x-1==x2 && y==y2 && temp[x-1][y]>=h[x][y]+1 || !(x-1==x2 && y==y2) && temp[x-1][y]>h[x][y]+1)) l.push(make_pair(v+1,make_pair(x-1,y)));
