const int Y[] = {0, 0, -1, 1};

bool check(pii v) {
    return v.first >= 0 && v.first < n && v.second >= 0 && v.second < n &&
           a[v.first][v.second] != 'Y' && a[v.first][v.second] != 'Z';
}

void bfs(int xs, int ys) {
    Matrix &cur = dst[xs][ys];

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            cur[i][j] = INF;

    cur[xs][ys] = 0;
    go.push(make_pair(xs, ys));

    while (!go.empty()) {
        pii v = go.front(); go.pop();

        if (cur[v.first][v.second] == dst[bad.first][bad.second][v.first][v.second] &&
            (bad.first != xs || bad.second != ys))
            continue;

        for (int k = 0; k < 4; ++k) {
            int nx = v.first + X[k];
            int ny = v.second + Y[k];
            pii nv = make_pair(nx, ny);

            if (check(nv) && cur[nx][ny] == INF &&
                cur[v.first][v.second] + 1 <= dst[bad.first][bad.second][nx][ny]) {
                cur[nx][ny] = cur[v.first][v.second] + 1;
                go.push(nv);
            }
        }
    }
}

