#include <bits/stdc++.h>

using namespace std;

const int MAXN = 300;

const int ROOM = -1;
const int REAC = -2;
const int BAD_REAC = -3;
const int CAPS = ROOM;

class Aresta {
public:
    int from, to, rev, flow, cap;
    Aresta(){}
    Aresta(int _from, int _to, int _rev, int _flow, int _cap){
        from = _from; to = _to; rev = _rev; flow = _flow; cap = _cap;
    }
    int residuo() {return cap-flow;}
};

class EdmondsKarp {
public:
    int size;
    vector<Aresta*> *grafo;
    Aresta **prev;
    bool *vis;

    EdmondsKarp(int tam){
        size = tam;
        grafo = new vector<Aresta*>[size];
        prev = new Aresta*[size];
        vis = new bool[size];
    }

    void limpa(){
        for (int i=0; i<size; i++){
            for (size_t j=0; j<grafo[i].size(); j++){
                delete grafo[i][j];
            }
            grafo[i].clear();
        }
    }

    void destroy(){
        limpa();
        delete prev;
        delete vis;
        delete this;
    }

    void add(int s, int t, int cap){
        Aresta *a = new Aresta(s, t, grafo[t].size(), 0, cap);
        Aresta *b = new Aresta(t, s, grafo[s].size(), 0, 0);
        grafo[s].push_back(a);
        grafo[t].push_back(b);
    }

    void undirectedAdd(int s, int t, int cap){
        Aresta *a = new Aresta(s, t, grafo[t].size(), 0, cap);
        Aresta *b = new Aresta(t, s, grafo[s].size(), 0, cap);
        grafo[s].push_back(a);
        grafo[t].push_back(b);
    }

    bool bfs(int source, int sink){
        for (int i=0; i<size; i++){
            prev[i] = NULL;
            vis[i] = false;
        }

        queue<int> fila;
        fila.push(source);
        vis[source] = 1;

        int atual;
        while (!fila.empty()){
            atual = fila.front(); fila.pop();

            if (atual == sink) return true;

            for (Aresta *a : grafo[atual]){
                if (!vis[a->to] && a->residuo() > 0){
                    prev[a->to] = a;
                    vis[a->to] = true;
                    fila.push(a->to);
                }
            }
        }

        return false;
    }

    int dfs(int source, int sink){
        int flow = INT_MAX;
        int v = sink;
        while (v != source){
            flow = min(flow, prev[v]->residuo());
            v = prev[v]->from;
        }

        v = sink;
        Aresta *a;
        while (v != source){
            a = prev[v];
            a->flow += flow;
            grafo[a->to][a->rev]->flow -= flow;
            v = a->from;
        }
        return flow;
    }

    long long int flow(int source, int sink){
        int flow = 0;
        while (bfs(source, sink)){
            flow += dfs(source, sink);
        }
        return flow;
    }
};

