class ArrayMaxFlow {
    int n, edgeCnt;
    vector<int> head;
    vector<int> to, cap, flow, nxt;
    vector<int> parent, parentEdge;

public:
    ArrayMaxFlow(int _n) : n(_n), edgeCnt(0), head(_n, -1), parent(_n), parentEdge(_n) {}

    void addEdge(int u, int v, int c) {
        to.push_back(v);
        cap.push_back(c);
        flow.push_back(0);
        nxt.push_back(head[u]);
        head[u] = edgeCnt++;

        to.push_back(u);
        cap.push_back(0);
        flow.push_back(0);
        nxt.push_back(head[v]);
        head[v] = edgeCnt++;
    }

    bool bfs(int s, int t) {
        fill(parent.begin(), parent.end(), -1);
        fill(parentEdge.begin(), parentEdge.end(), -1);

        queue<int> q;
        q.push(s);
        parent[s] = s;

        while (!q.empty()) {
            int u = q.front();
            q.pop();

            for (int e = head[u]; e != -1; e = nxt[e]) {
                int v = to[e];

                if (parent[v] == -1 && cap[e] - flow[e] > 0) {
                    parent[v] = u;
                    parentEdge[v] = e;

                    if (v == t) return true;
                    q.push(v);
                }
            }
        }

        return false;
    }

    int augment(int s, int t) {
        int pushed = INT_MAX;

        for (int v = t; v != s; v = parent[v]) {
            int e = parentEdge[v];
            pushed = min(pushed, cap[e] - flow[e]);
        }

        for (int v = t; v != s; v = parent[v]) {
            int e = parentEdge[v];
            flow[e] += pushed;
            flow[e ^ 1] -= pushed;
        }

        return pushed;
    }

    long long maxFlow(int s, int t) {
        long long total = 0;

        while (bfs(s, t)) {
            total += augment(s, t);
        }

        return total;
    }
};

