           board[r][c] != 'Y' && board[r][c] != 'Z';
}

vector<vector<int>> computeDistances(int sr, int sc, const vector<string>& board) {
    int n = (int)board.size();
    vector<vector<int>> d(n, vector<int>(n, INF));
    deque<pair<int,int>> q;
    d[sr][sc] = 0;
    q.push_back(make_pair(sr, sc));

    while (!q.empty()) {
        pair<int,int> cur = q.front();
        q.pop_front();

        for (int dir = 0; dir < 4; ++dir) {
            int nr = cur.first + mx[dir];
            int nc = cur.second + my[dir];

            if (!reachable(nr, nc, board) || d[nr][nc] != INF) continue;

            d[nr][nc] = d[cur.first][cur.second] + 1;
            q.push_back(make_pair(nr, nc));
        }
    }

    return d;
}

void build() {
    int n, timeLimit;
    cin >> n >> timeLimit;

    vector<string> grid1(n), grid2(n);
    for (int i = 0; i < n; ++i) cin >> grid1[i];
    for (int i = 0; i < n; ++i) cin >> grid2[i];

