const ll INF = 1e17 + 7;
const int MAXN = 1001;

class Solver {
    int dx[4] = {0, 0, -1, 1};
    int dy[4] = {-1, 1, 0, 0};

    vector<int> graph[MAXN];
    bool used[MAXN];
    int match[MAXN];

    bool cellOk(int x, int y, const vector<string>& board) {
        return x >= 0 && y >= 0 && x < (int)board.size() && y < (int)board.size() &&
               board[x][y] != 'Y' && board[x][y] != 'Z';
    }

    vector<vector<int>> bfs(int sx, int sy, const vector<string>& board) {
        int n = (int)board.size();
        vector<vector<int>> dist(n, vector<int>(n, INF));
        queue<pair<int,int>> q;
        dist[sx][sy] = 0;
        q.push({sx, sy});

        while (!q.empty()) {
            pair<int,int> v = q.front();
            q.pop();

            for (int i = 0; i < 4; ++i) {
                int nx = v.first + dx[i];
                int ny = v.second + dy[i];

                if (!cellOk(nx, ny, board) || dist[nx][ny] != INF) continue;

                dist[nx][ny] = dist[v.first][v.second] + 1;
                q.push({nx, ny});
            }
        }

        return dist;
    }

    void addEdge(const vector<string>& a, const vector<string>& b, int i, int j, int x, int y) {
        int L = 100 * i + 10 * j;
        int R = 100 * x + 10 * y;

        for (int u = 1; u <= a[i][j] - '0'; ++u) {
            for (int v = 1; v <= b[x][y] - '0'; ++v) {
                graph[L + u].push_back(R + v);
            }
        }
    }

    bool kuhn(int v) {
        if (used[v]) return false;
        used[v] = true;

        for (int to : graph[v]) {
            if (match[to] == 0 || kuhn(match[to])) {
                match[to] = v;
                return true;
            }
        }

        return false;
    }

public:
    void run() {
        int n, t;
        cin >> n >> t;

        vector<string> a(n), b(n);
        for (auto& row : a) cin >> row;
        for (auto& row : b) cin >> row;

        int zx = 0, zy = 0;
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                if (a[i][j] == 'Z') zx = i, zy = j;
            }
        }

        vector<vector<int>> toZ = bfs(zx, zy, a);

        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                if (!cellOk(i, j, a)) continue;

                vector<vector<int>> cur = bfs(i, j, a);

                for (int x = 0; x < n; ++x) {
                    for (int y = 0; y < n; ++y) {
                        if (!cellOk(x, y, a) || cur[x][y] > t || cur[x][y] > toZ[x][y])
                            continue;

                        if (cur[x][y] == toZ[x][y]) {
                            bool good = false;
                            for (int d = 0; d < 4; ++d) {
                                int nx = x + dx[d];
                                int ny = y + dy[d];
                                if (!cellOk(nx, ny, a) || cur[nx][ny] >= toZ[nx][ny])
                                    continue;
                                good = true;
                            }
                            if (!good) continue;
                        }

                        addEdge(a, b, i, j, x, y);
                    }
                }
            }
        }

        for (int i = 0; i < MAXN; ++i) {
            kuhn(i);
            memset(used, 0, sizeof(used));
        }

        int answer = 0;
        for (int i = 0; i < MAXN; ++i) answer += (match[i] != 0);

        cout << answer;
    }
};

