struct MaxFlow {
    vector<int> head, to, nxt, cap, flow, level, it;
    int s, t, n;
    void init(int n_) {
        n = n_;
        head.assign(n, -1);
        to.clear();
        nxt.clear();
        cap.clear();
        flow.clear();
        level.resize(n);
        it.resize(n);
    }
    void addEdge(int u, int v, int c) {
        int id = (int)to.size();
        to.push_back(v);
        cap.push_back(c);
        flow.push_back(0);
        nxt.push_back(head[u]);
        head[u] = id;
        to.push_back(u);
        cap.push_back(0);
        flow.push_back(0);
        nxt.push_back(head[v]);
        head[v] = id ^ 1;
    }
    bool bfs() {
        fill(level.begin(), level.end(), -1);
        queue<int> q;
        level[s] = 0;
        q.push(s);
        while (!q.empty()) {
            int u = q.front();
            q.pop();
            for (int e = head[u]; e != -1; e = nxt[e]) {
                int v = to[e];
                if (level[v] == -1 && cap[e] > flow[e]) {
                    level[v] = level[u] + 1;
                    q.push(v);
                }
            }
        }
        return level[t] != -1;
    }
    int dfs(int u, int a) {
        if (u == t || a == 0) return a;
        int ret = 0;
        for (int &e = it[u]; e != -1; e = nxt[e]) {
            int v = to[e];
            if (level[v] == level[u] + 1 && cap[e] > flow[e]) {
                int f = dfs(v, min(a, cap[e] - flow[e]));
                if (f > 0) {
                    flow[e] += f;
                    flow[e ^ 1] -= f;
                    a -= f;
                    ret += f;
                    if (a == 0) break;
                }
            }
        }
        return ret;
    }
    int maxflow(int S, int T) {
        s = S;
        t = T;
        int ans = 0;
        while (bfs()) {
            it = head;
            ans += dfs(s, INF);
        }
        return ans;
    }
} mf;

