    int qf = 0, qr = 0;
    q[qr++] = t; inq[t] = 1; gap[0]++; dist[t] = 0;
    while (qf < qr) {
        int u = q[qf++];
        for (int i = head[u]; i != -1; i = adj[i])
            if (!inq[edge[i].v]) {
                int v = edge[i].v;
                q[qr++] = v;
                inq[v] = 1;
                dist[v] = dist[u] + 1;
                gap[dist[v]]++;
                arc[v] = head[v];
            }
    }
    int low = INF, u = s, ans = 0;
    pre[s] = s;
    while (dist[s] < t) {
        bool flag = false;
        for (int &i = arc[u]; i != -1; i = adj[i])
            if (edge[i].w && dist[edge[i].v] + 1 == dist[u]) {
                flag = true;
                low = min(low, edge[i].w);
                pre[edge[i].v] = u;
                u = edge[i].v;
                if (u == t) {
                    while (u != s) {
                        u = pre[u];
                        edge[arc[u]].w -= low;
                        edge[arc[u] ^ 1].w += low;
                    }
                    ans += low;
                    low = INF;
                }
                break;
            }
        if (flag) continue;
        int mindis = t + 1;
        for (int i = head[u]; i != -1; i = adj[i])
            if (edge[i].w && mindis > dist[edge[i].v]) {
                mindis = dist[edge[i].v];
                arc[u] = i;
            }
        gap[dist[u]]--;
        if (gap[dist[u]] == 0) return ans;
        dist[u] = mindis + 1;
        gap[dist[u]]++;
        u = pre[u];
    }
    return ans;
}

