        for (int j = 0; j < M; ++j)
        {
            if (s[j] == 'Z')
            {
                Cell c;
                c.r = i;
                c.c = j;
                c.dis = 0;
                q.push(c);
            }
            else if (s[j] != 'Y')
            {
                walk[i][j] = true;
                zd[i][j] = LIM;
                int k = s[j] - '0';
                if (k > 0)
                {
                    src[i][j] = ++N;
                    cap[0][N] = k;
                    SUP += k;
                }
            }
        }
    }
    memcpy(walkSave, walk, sizeof(walk));

    for (int i = 0; i < M; ++i)
    {
        scanf("%s", s);
        for (int j = 0; j < M; ++j)
        {
            if (s[j] == 'Z' || s[j] == 'Y')
                continue;
            int k = s[j] - '0';
            if (k > 0)
            {
                dst[i][j] = ++N;
                cap[N][M * M + 1] = k;
            }
        }
    }

    sink = N + 1;
    if (N != M * M)
    {
        for (int i = 0; i < M; ++i)
            for (int j = 0; j < M; ++j)
                if (dst[i][j] > 0)
                {
                    int v = dst[i][j];
                    cap[v][sink] = cap[v][M * M + 1];
                    cap[v][M * M + 1] = 0;
                }
    }

    while (!q.empty())
    {
        Cell cur = q.front();
        q.pop();
        int i = cur.r, j = cur.c;
        zd[i][j] = cur.dis;
        for (int d = 0; d < 4; ++d)
        {
            int ni = i + dr[d], nj = j + dc[d];
            if (inside(ni, nj) && walk[ni][nj])
            {
                walk[ni][nj] = false;
                Cell nxt;
                nxt.r = ni;
                nxt.c = nj;
                nxt.dis = cur.dis + 1;
                q.push(nxt);
            }
        }
    }

    for (int i = 0; i < M; ++i)
    {
        for (int j = 0; j < M; ++j)
        {
            if (src[i][j] == 0)
                continue;
            memcpy(walk, walkSave, sizeof(walkSave));
            walk[i][j] = false;
            Cell st;
            st.r = i;
            st.c = j;
            st.dis = 0;
            q.push(st);
            while (!q.empty())
            {
                Cell cur = q.front();
                q.pop();
                int x = cur.r, y = cur.c;
                if (dst[x][y] > 0 && cur.dis <= zd[x][y])
                    cap[src[i][j]][dst[x][y]] = SUP;
                if (cur.dis + 1 > LIM || cur.dis >= zd[x][y])
                    continue;
                for (int d = 0; d < 4; ++d)
                {
                    int nx = x + dr[d], ny = y + dc[d];
                    if (inside(nx, ny) && walk[nx][ny])
                    {
                        walk[nx][ny] = false;
                        Cell nxt;
                        nxt.r = nx;
                        nxt.c = ny;
                        nxt.dis = cur.dis + 1;
                        q.push(nxt);
                    }
                }
            }
        }
    }

    gap[0] = N + 2;
    alive = true;
    while (alive && lev[0] <= N + 2)
        while (augmentingPath())
            updateFlow();

    int ans = 0;
    for (int i = 1; i <= N; ++i)
        ans += flow[i][sink];
    printf("%d\n", ans);
    return 0;
}

