            }
        }
    }

    graph.assign(n + 2, vector<Edge>());
    for (int u = 0; u <= n + 1; ++u)
        for (int v = 0; v <= n + 1; ++v)
            if (capacity[u][v] > 0)
                addEdge(u, v, capacity[u][v]);

    int maxflow = 0;
    while (true)
    {
        vector<int> parent(n + 2, -1), pedge(n + 2, -1);
        queue<int> qq;
