int level[MAXN], it[MAXN];

bool bfsLevel() {
    fill(level, level + T + 1, -1);
    queue<int> q;
    level[S] = 0;
    q.push(S);

    while (!q.empty()) {
        int u = q.front();
        q.pop();
        for (int e = head[u]; e != -1; e = nxtEdge[e]) {
            int v = to[e];
            if (cap[e] > 0 && level[v] == -1) {
                level[v] = level[u] + 1;
                q.push(v);
            }
        }
    }
    return level[T] != -1;
}

int dfs(int u, int f) {
    if (u == T) return f;

    for (int &e = it[u]; e != -1; e = nxtEdge[e]) {
        int v = to[e];
        if (cap[e] > 0 && level[v] == level[u] + 1) {
            int pushed = dfs(v, min(f, cap[e]));
            if (pushed) {
                cap[e] -= pushed;
                cap[e ^ 1] += pushed;
                return pushed;
            }
        }
    }
    return 0;
}

int maxFlow() {
    int ans = 0;
    while (bfsLevel()) {
        for (int i = 0; i <= T; ++i) it[i] = head[i];
        while (int pushed = dfs(S, 10000000)) ans += pushed;
    }
    return ans;
}

