}

void addEdge(int u, int v, int c) {
    edges[tot] = {v, head[u], c};
    head[u] = tot++;
    edges[tot] = {u, head[v], 0};
    head[v] = tot++;
}

void buildNetwork(int sx, int sy) {
    if (g2[sx][sy] != 0) {
        addEdge(id[sx][sy] + cnt, T, g2[sx][sy] - '0');
    }
    if (g1[sx][sy] == '0') return;
    addEdge(S, id[sx][sy], g1[sx][sy] - '0');
    if (g2[sx][sy] != 0) {
        addEdge(id[sx][sy], id[sx][sy] + cnt, 10);
    }

