                int nx = x + dx[i];
                int ny = y + dy[i];
                if (ok(nx, ny) && d2[nx][ny] < 0) {
                    d2[nx][ny] = d2[x][y] + 1;
                    qb.push_back({nx, ny});
                }
            }
