    for (int b = 1; b <= n; ++b) {
        pair<ll, ll> ap = geta(x, y, b);

        if (!have) {
            bestA = ap.first;
            bestB = b;
            have = true;
        } else if (is_better(ap.first, b, bestA, bestB, x, y)) {
            bestA = ap.first;
            bestB = b;
        }

        if (is_better(ap.second, b, bestA, bestB, x, y)) {
            bestA = ap.second;
            bestB = b;
        }
    }

    cout << bestA << "/" << bestB << '\n';
}

