ll bestErrN = 100000, bestErrD = 1;
ll ansN = 0, ansD = 0;

ll gcd(ll a, ll b) {
    while (b != 0) {
        ll t = a % b;
        a = b;
        b = t;
    }
    return a;
}

void process(ll x, ll y, ll den, ll num) {
    if (num < 0) return;

    ll g = gcd(num, den);
    num /= g;
    den /= g;

    ll diffN = den * x - num * y;
    if (diffN < 0) diffN = -diffN;
    ll diffD = den * y;

    g = gcd(diffN, diffD);
    diffN /= g;
    diffD /= g;

    if (diffN * bestErrD < bestErrN * diffD) {
        bestErrN = diffN;
        bestErrD = diffD;
        ansN = num;
        ansD = den;
    } else if (diffN * bestErrD == bestErrN * diffD) {
        if (den < ansD || (den == ansD && num < ansN)) {
            ansN = num;
            ansD = den;
        }
    }
}

