    long long bestN = 100000;
    long long bestD = 1;
    long long chosenN = 0;
    long long chosenD = 0;

    void consider(long long x, long long y, long long d, long long n) {
        if (n < 0) return;

        long long g = std::gcd(n, d);
        n /= g;
        d /= g;

        long long eN = d * x - n * y;
        if (eN < 0) eN = -eN;
        long long eD = d * y;

        g = std::gcd(eN, eD);
        eN /= g;
        eD /= g;

        long long lhs = eN * bestD;
        long long rhs = bestN * eD;

        if (lhs < rhs) {
            bestN = eN;
            bestD = eD;
            chosenN = n;
            chosenD = d;
        } else if (lhs == rhs) {
            if (d < chosenD || (d == chosenD && n < chosenN)) {
                chosenN = n;
                chosenD = d;
            }
        }
    }
};

