#include <iostream>
#include <cstdlib>
using namespace std;

int main() {
    long long x, y, n;
    cin >> x >> y >> n;

    long long bestNumerator = -1;
    long long bestDenominator;

    for (long long denominator = 1; denominator <= n; ++denominator) {
        long long numerator = denominator * x / y;

        long long remainder = denominator * x - numerator * y;
        long long highRemainder = (numerator + 1) * y - denominator * x;
        if (remainder > highRemainder) {
            ++numerator;
        }

        if (bestNumerator == -1 ||
            llabs(bestNumerator * y - x * bestDenominator) * denominator >
            llabs(numerator * y - x * denominator) * bestDenominator) {
            bestNumerator = numerator;
            bestDenominator = denominator;
        }
    }

    cout << bestNumerator << "/" << bestDenominator << endl;
    return 0;
}

#include <iostream>
#include <cstdlib>
using namespace std;

bool is_better(long long num, long long den,
               long long bestNum, long long bestDen,
               long long x, long long y) {
    if (bestNum == -1) return true;
    long long oldError = llabs(bestNum * y - x * bestDen) * den;
    long long candidateError = llabs(num * y - x * den) * bestDen;
    return oldError > candidateError;
}

int main() {
    long long x, y, n;
    cin >> x >> y >> n;

    long long a = -1;
    long long b;
    long long i = 1;

    while (i <= n) {
        long long j = i * x / y;
        if (i * x - j * y > (j + 1) * y - i * x) {
            ++j;
        }

        if (a == -1 || is_better(j, i, a, b, x, y)) {
            a = j;
            b = i;
        }

        ++i;
    }

    cout << a << "/" << b << endl;
    return 0;
}

