struct Fraction {
    long long num;
    long long den;
};

int main() {
    long long x, y, n;
    cin >> x >> y >> n;

    Fraction best;
    best.num = -1;

    for (long long i = 1; i <= n; ++i) {
        long long j = i * x / y;
        long long lowerDiff = i * x - j * y;
        long long upperDiff = (j + 1) * y - i * x;

        if (lowerDiff > upperDiff) {
            ++j;
        }

        if (best.num == -1 ||
            llabs(best.num * y - x * best.den) * i >
            llabs(j * y - x * i) * best.den) {
            best.num = j;
            best.den = i;
        }
    }

    cout << best.num << "/" << best.den << endl;
    return 0;
}

