    long long bestA = -1;
    long long bestB;
    long long i = 1;

    while (i <= n) {
        lldiv_t qr = lldiv(i * x, y);
        long long j = qr.quot;
        long long r = qr.rem;

        if (r > y - r) {
            ++j;
        }

        if (bestA == -1 ||
            llabs(bestA * y - x * bestB) * i >
            llabs(j * y - x * i) * bestB) {
            bestA = j;
            bestB = i;
        }

        ++i;
    }

    cout << bestA << "/" << bestB << endl;
    return 0;
}

#include <iostream>
#include <cstdlib>
using namespace std;

int main() {
    long long x, y, n;
    cin >> x >> y >> n;

    long long a = -1;
    long long b;

    auto consider = [&](long long num, long long den) {
        if (a == -1) {
            a = num;
            b = den;
            return;
        }

        long long oldError = llabs(a * y - x * b) * den;
        long long newError = llabs(num * y - x * den) * b;
        if (oldError > newError) {
            a = num;
            b = den;
        }
    };

    for (long long i = 1; i <= n; ++i) {
        long long prod = i * x;
        long long j = prod / y;

        if (prod - j * y > (j + 1) * y - prod) {
            ++j;
        }

        consider(j, i);
    }

    cout << a << "/" << b << endl;
    return 0;
}

