int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int x, y, maxDen;
    cin >> x >> y >> maxDen;

    const double eps = 1e-15;
    double target = static_cast<double>(x) / static_cast<double>(y);

    int bestNumer = x;
    int bestDenom = y;
    double bestError = 1000000.0;

    for (int den = 1; den <= maxDen; ++den) {
        double scaled = static_cast<double>(x) * static_cast<double>(den) / static_cast<double>(y);
        double low = floor(scaled);
        double high = ceil(scaled);

        double errorLow = abs(low / static_cast<double>(den) - target);
        double errorHigh = abs(high / static_cast<double>(den) - target);

        double chosenValue;
        double chosenError;

        if (errorHigh == errorLow) {
            chosenValue = low;
            chosenError = errorLow;
        } else if (errorHigh < errorLow) {
            chosenValue = high;
            chosenError = errorHigh;
        } else {
            chosenValue = low;
            chosenError = errorLow;
        }

        if (chosenError < bestError - eps) {
            bestNumer = static_cast<int>(chosenValue);
            bestDenom = den;
            bestError = chosenError;
        }
    }

    cout << bestNumer << "/" << bestDenom;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios_base::sync_with_stdio(0);
    cin.tie(0);

    int x, y, nn;
    cin >> x >> y >> nn;

    const double eps = 0.000000000000001;
    double target = (double)x / (double)y;

    int bestNum = x;
    int bestDen = y;
    double bestDiff = 1000000.0;

    int d = 1;
    while (d <= nn) {
        double scaled = (double)x * d / (double)y;
        double low = floor(scaled);
        double high = ceil(scaled);

        double values[2] = { low, high };
        double diffs[2] = {
            abs(values[0] / d - target),
            abs(values[1] / d - target)
        };

        int chosen = 0;
        if (diffs[1] != diffs[0] && diffs[1] < diffs[0]) chosen = 1;

        if (diffs[chosen] < bestDiff - eps) {
            bestNum = (int)values[chosen];
            bestDen = d;
            bestDiff = diffs[chosen];
        }

        ++d;
    }

    cout << bestNum << "/" << bestDen;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

void tryDenominator(int x, int denominator, int y, double target, double eps, int &bestNum, int &bestDen, double &bestDiff) {
    double scaled = (double)x * denominator / (double)y;
    double low = floor(scaled);
    double high = ceil(scaled);

    double diffLow = abs(low / denominator - target);
    double diffHigh = abs(high / denominator - target);

    double chosenValue;
    double chosenDiff;

    if (diffHigh == diffLow) {
        chosenValue = low;
        chosenDiff = diffLow;
    } else if (diffHigh < diffLow) {
        chosenValue = high;
        chosenDiff = diffHigh;
    } else {
        chosenValue = low;
        chosenDiff = diffLow;
    }

    if (chosenDiff < bestDiff - eps) {
        bestNum = (int)chosenValue;
        bestDen = denominator;
        bestDiff = chosenDiff;
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int x, y, nn;
    cin >> x >> y >> nn;

    double eps = 0.000000000000001;
    double target = (double)x / (double)y;

    int bestNum = x;
    int bestDen = y;
    double bestDiff = 1000000.0;

    for (int denominator = 1; denominator <= nn; ++denominator) {
        tryDenominator(x, denominator, y, target, eps, bestNum, bestDen, bestDiff);
    }

    cout << bestNum << "/" << bestDen;
    return 0;
}

