{
    long long x, y, limit;
    while (scanf("%lld%lld%lld", &x, &y, &limit) == 3)
    {
        long long num, den, big, small, rem = 1, quot;
        float best, err;

        if (y <= limit)
        {
            num = x;
            den = y;
        }
        else
        {
            best = 1.0f;
            for (long long i = 1; i <= limit; i++)
            {
                quot = i * x / y;

                err = (float)((double)x / (double)y - (double)quot / (double)i);
                if (err < best)
                {
                    best = err;
                    num = quot;
                    den = i;
                }

                err = (float)((double)(quot + 1) / (double)i - (double)x / (double)y);
                if (err < best)
                {
                    best = err;
                    num = quot + 1;
                    den = i;
                }
            }
        }

        if (num > den) { big = num; small = den; }
        else { big = den; small = num; }

        if (small == 0)
        {
            big = 1;
        }
        else
        {
            while (small != 0)
            {
                rem = big % small;
                big = small;
                small = rem;
            }
        }

        if (rem != 1)
        {
            num /= big;
            den /= big;
        }

        printf("%lld/%lld\n", num, den);
        fflush(stdout);
    }

    return 0;
}

