#include <iostream>
using namespace std;

struct Fraction
{
    long long num;
    long long den;
};

void reduce(Fraction &f)
{
    long long greater = f.num > f.den ? f.num : f.den;
    long long smaller = f.num > f.den ? f.den : f.num;

    if (smaller == 0)
    {
        greater = 1;
        return;
    }

    long long remainder;
    while (smaller != 0)
    {
        remainder = greater % smaller;
        greater = smaller;
        smaller = remainder;
    }

    f.num /= greater;
    f.den /= greater;
}

int main()
{
    long long x, y, limit;
    while (cin >> x >> y >> limit)
    {
        Fraction ans;

        if (y <= limit)
        {
            ans.num = x;
            ans.den = y;
        }
        else
        {
            float best = 1.0f;
            float err;

            for (long long i = 1; i <= limit; i++)
            {
                long long k = i * x / y;

                err = (float)((double)x / (double)y - (double)k / (double)i);
                if (err < best)
                {
                    best = err;
                    ans.num = k;
                    ans.den = i;
                }

                err = (float)((double)(k + 1) / (double)i - (double)x / (double)y);
                if (err < best)
                {
                    best = err;
                    ans.num = k + 1;
                    ans.den = i;
                }
            }
        }

        reduce(ans);
        cout << ans.num << "/" << ans.den << endl;
    }

    return 0;
}

#include <iostream>
using namespace std;

void search_best(long long x, long long y, long long limit, long long frac[2])
{
    float best = 1.0f;
    float err;

    for (long long i = 1; i <= limit; i++)
    {
        long long k = i * x / y;

        err = (float)((double)x / (double)y - (double)k / (double)i);
        if (err < best)
        {
            best = err;
            frac[0] = k;
            frac[1] = i;
        }

        err = (float)((double)(k + 1) / (double)i - (double)x / (double)y);
        if (err < best)
        {
            best = err;
            frac[0] = k + 1;
            frac[1] = i;
        }
    }
}

void reduce_array(long long frac[2])
{
    long long greater = frac[0] > frac[1] ? frac[0] : frac[1];
    long long smaller = frac[0] > frac[1] ? frac[1] : frac[0];
    long long rem = 1;

    if (smaller == 0)
    {
        greater = 1;
    }
    else
    {
        while (smaller != 0)
        {
            rem = greater % smaller;
            greater = smaller;
            smaller = rem;
        }
    }

    if (rem != 1)
    {
        frac[0] /= greater;
        frac[1] /= greater;
    }
}

int main()
{
    long long x, y, limit;
    while (cin >> x >> y >> limit)
    {
        long long ans[2];

        if (y <= limit)
        {
            ans[0] = x;
            ans[1] = y;
        }
        else
        {
            search_best(x, y, limit, ans);
        }

        reduce_array(ans);
        cout << ans[0] << "/" << ans[1] << endl;
    }

    return 0;
}

