static void update(double a, double b, double target, double &bestA, double &bestB, double &bestError) {
    double err = fabs(a / b - target);
    if (err < bestError || (err == bestError && a < bestA)) {
        bestA = a;
        bestB = b;
        bestError = err;
    }
}

