#include <bits/stdc++.h>
using namespace std;

using ll = long long;
using Rat = pair<ll, ll>;

int main() {
    ios_base::sync_with_stdio(0), cin.tie(0), cout.tie(0);

    ll x, y, n;
    cin >> x >> y >> n;

    ll g = gcd(x, y);
    x /= g;
    y /= g;

    Rat target{x, y};
    Rat bestDiff{1000000000000LL, 1};
    Rat best{0, 0};

    auto absSub = [](Rat a, Rat b) -> Rat {
        ll l = lcm(a.second, b.second);
        ll num = a.first * (l / a.second) - b.first * (l / b.second);
        if (num < 0) num = -num;
        ll d = gcd(num, l);
        return {num / d, l / d};
    };

    auto cmp = [](Rat a, Rat b) -> int {
        ll l = lcm(a.second, b.second);
        ll na = a.first * (l / a.second);
        ll nb = b.first * (l / b.second);
        if (na == nb) return 0;
        return na < nb ? -1 : 1;
    };

    auto relax = [&](Rat cand, Rat diff) {
        int c = cmp(diff, bestDiff);
        if (c == 0) {
            if (cand.second < best.second ||
                (cand.second == best.second && cand.first < best.first)) {
                best = cand;
            }
        } else if (c < 0) {
            bestDiff = diff;
            best = cand;
        }
    };

    for (ll b = 1; b <= n; ++b) {
        ll lo = 0;
        double hiLimit = (double)x / y;
        hiLimit += (double)bestDiff.first / bestDiff.second;
        ll hi = (ll)((hiLimit + 2.0) * b);

        while (lo <= hi) {
            ll mid = lo + (hi - lo) / 2;
            Rat cand{mid, b};
            relax(cand, absSub(target, cand));

            if (cmp(cand, target) < 0)
                lo = mid + 1;
            else
                hi = mid - 1;
        }
    }

    cout << best.first << "/" << best.second;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;

struct Rational {
    ll num, den;

    Rational(ll n = 0, ll d = 1) : num(n), den(d) {}

    Rational operator-(const Rational& other) const {
        ll l = lcm(den, other.den);
        ll n1 = num * (l / den);
        ll n2 = other.num * (l / other.den);
        ll d = n1 - n2;
        ll g = gcd(std::abs(d), l);
        return Rational(d / g, l / g);
    }

    Rational abs_value() const {
        if (num < 0) return Rational(-num, den);
        return *this;
    }

    int compare(const Rational& other) const {
        ll l = lcm(den, other.den);
        ll n1 = num * (l / den);
        ll n2 = other.num * (l / other.den);
        if (n1 == n2) return 0;
        return n1 < n2 ? -1 : 1;
    }
};

int main() {
    ios::sync_with_stdio(0), cin.tie(0);

    ll x, y, n;
    cin >> x >> y >> n;
    ll g = gcd(x, y);
    x /= g;
    y /= g;

    Rational target(x, y);
    Rational bestDiff(1000000000000LL, 1);
    Rational best(0, 0);

    for (ll b = 1; b <= n; ++b) {
        ll lo = 0;
        double lim = (double)x / y;
        lim += (double)bestDiff.num / bestDiff.den;
        ll hi = (ll)((lim + 2.0) * b);

        while (lo <= hi) {
            ll mid = lo + (hi - lo) / 2;
            Rational cand(mid, b);
            Rational diff = (target - cand).abs_value();

            int c = diff.compare(bestDiff);
            if (c == 0) {
                if (cand.den < best.den ||
                    (cand.den == best.den && cand.num < best.num)) {
                    best = cand;
                }
            } else if (c < 0) {
                bestDiff = diff;
                best = cand;
            }

            if (cand.compare(target) < 0)
                lo = mid + 1;
            else
                hi = mid - 1;
        }
    }

    cout << best.num << "/" << best.den;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
typedef struct Frac { ll p, q; } Frac;

void abs_sub(Frac a, Frac b, Frac* out) {
    ll l = lcm(a.q, b.q);
    ll na = a.p * (l / a.q);
    ll nb = b.p * (l / b.q);
    ll d = na - nb;
    if (d < 0) d = -d;
    ll g = gcd(d, l);
    out->p = d / g;
    out->q = l / g;
}

int cmp(Frac a, Frac b) {
    ll l = lcm(a.q, b.q);
    ll na = a.p * (l / a.q);
    ll nb = b.p * (l / b.q);
    if (na == nb) return 0;
    return na < nb ? -1 : 1;
}

int main() {
    ios_base::sync_with_stdio(false), cin.tie(nullptr);

    ll x, y, n;
    cin >> x >> y >> n;

    ll g = gcd(x, y);
    x /= g;
    y /= g;

    Frac target = {x, y};
    Frac bestDiff = {1000000000000LL, 1};
    Frac best = {0, 0};

    for (ll b = 1; b <= n; ++b) {
        ll l = 0;
        double bound = (double)x / y + (double)bestDiff.p / bestDiff.q;
        ll r = (ll)((bound + 2.0) * (double)b);

        while (l <= r) {
            ll mid = l + (r - l) / 2;
            Frac cand = {mid, b};
            Frac diff;
            abs_sub(target, cand, &diff);

            int c = cmp(diff, bestDiff);
            if (c == 0) {
                if (cand.q < best.q || (cand.q == best.q && cand.p < best.p))
                    best = cand;
            } else if (c < 0) {
                bestDiff = diff;
                best = cand;
            }

            if (cmp(cand, target) < 0)
                l = mid + 1;
            else
                r = mid - 1;
        }
    }

    cout << best.p << "/" << best.q;
    return 0;
}

