        while (denom * x > right) {
            left += y;
            right += y;
        }
        if (denom * x >= left && denom * x <= right) {
            ll candL = left / y;
            ll candR = right / y;
            double distL = fabs(goal - (double)candL / denom);
            double distR = fabs(goal - (double)candR / denom);
            bool useR = distR < distL;
