        ll w = x * (L / y);
        ll step = L / i;
        ll floor_num = w / step;
        ll floor_val = floor_num * step;
        double diff_floor = (double)(w - floor_val) / (double)L;
        if (best > diff_floor) {
            best = diff_floor;
            best_num = floor_num;
            best_den = i;
