        swap(a, b);
    }
    return a;
}

ll lcm(ll a, ll b) {
    return a * b / gcd(a, b);
}

int main() {
    cin >> x >> y >> n;
    if (y <= n) {
        while (gcd(x, y) > 1) {
            ll g = gcd(x, y);
            x /= g;
            y /= g;
        }
        cout << x << "/" << y;
        return 0;
    }
    for (ll i = 1; i <= n; ++i) {
        ll L = lcm(i, y);
        ll w = x * (L / y);
        ll step = L / i;
        ll floor_num = w / step;
        double diff_floor = (double)(w - floor_num * step) / (double)L;
        if (best > diff_floor) {
            best = diff_floor;
            best_p = floor_num;
            best_q = i;
        }
        ll ceil_num = (w + step - 1) / step;
        double diff_ceil = (double)(ceil_num * step - w) / (double)L;
        if (best > diff_ceil) {
            best = diff_ceil;
            best_p = ceil_num;
            best_q = i;
        }
    }
    ll g = gcd(best_p, best_q);
    best_p /= g;
    best_q /= g;
    cout << best_p << "/" << best_q;
    return 0;
}

