#include <bits/stdc++.h>
using namespace std;

using ll = long long;

ll gcd(ll a, ll b) {
    return b == 0 ? a : gcd(b, a % b);
}

ll rounded_value(double z) {
    double frac = z - floor(z);
    if (frac <= 0.5) return (ll)floor(z);
    return (ll)floor(z) + 1;
}

struct Rational {
    ll num, den;

    void reduce() {
        ll g = gcd(num, den);
        num /= g;
        den /= g;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

#ifndef ONLINE_JUDGE
    freopen("input.txt", "r", stdin);
    freopen("output.txt", "w", stdout);
#endif

    ll t = 1;
    while (t--) {
        double x, y, n;
        cin >> x >> y >> n;

        double req = x / y;
        double mn = 1e9;
        Rational ans;

        if (y <= n) {
            ans.num = (ll)x;
            ans.den = (ll)y;
        } else {
            for (ll deno = (ll)n; deno >= 1; --deno) {
                double z = (double)deno * req;
                ll num = rounded_value(z);
                double now = (double)num / (double)deno;
                double diff = std::abs(now - req);

                if (diff <= mn) {
                    mn = diff;
                    ans.num = num;
                    ans.den = deno;
                }
            }
        }

        ans.reduce();
        cout << ans.num << "/" << ans.den << "\n";
    }

    return 0;
}

