#include <iostream>
#include <cmath>

using namespace std;

int find_gcd(int x, int y)
{
    int gcd = (x > y) ? x : y;
    while (true)
    {
        if (x % gcd == 0 && y % gcd == 0)
            break;
        gcd--;
    }
    return gcd;
}

void diff(double x, double y, double a, double b, double &num, double &den)
{
    num = fabs(x * b - y * a);
    den = y * b;
}

void reduce_fraction(int &num, int &den)
{
    int g = find_gcd(num, den);
    if (g != 1)
    {
        num = num / g;
        den = den / g;
    }
}

int main()
{
