int gcdValue(int a, int b)
{
    int g = (a > b) ? a : b;
    while (a % g != 0 || b % g != 0)
    {
        --g;
    }
    return g;
}

void dist(double x, double y, double a, double b, double &num, double &den)
{
    num = fabs(x * b - y * a);
    den = y * b;
}

void tryCandidate(double candidate, double denom, double x, double y,
                  double &currentBest, int &bestA, int &bestB)
{
    double num, den, d;
    dist(x, y, candidate, denom, num, den);
    d = num / den;

    if (d < currentBest)
    {
        currentBest = d;
        bestA = (int)candidate;
        bestB = (int)denom;
    }
    else if (d == currentBest && candidate < bestA)
    {
        bestA = (int)candidate;
        bestB = (int)denom;
    }
}

int main()
{
    double x, y, n, a, b;
    double best = 1000000.0;
    int bestA = 0;
    int bestB = 0;

    cin >> x >> y >> n;

